  const _solidInputsSame = (prev, next) => {
    if (prev === next) return true;
    if (!prev || !next || prev.length !== next.length) return false;
    for (let i = 0; i < next.length; i++) {
      const a = prev[i], b = next[i];
      if (!a || !b) return false;
      if (a.id !== b.id || a.label !== b.label || a.color !== b.color) return false;
      if (a.blocks !== b.blocks) return false;   // 形が変わったかは blocks の参照で分かる
    }
    return true;
  };
  useEffect(() => {
    if (_solidSyncBlockedForRef.current === buildings) return; // ブロック中
    if (ppDragRef.current) return; // pushpullドラッグ中はsolids再生成禁止
    if (_prevBuildingsRef.current !== buildings) {
      const prevBuildings = _prevBuildingsRef.current;
      // 【形に関係ない変更なら作り直さない】機器・壁・扉・階の編集はここで抜ける。
      // 参照だけ進めておけば、次に本当に形が変わったとき正しく比較できる
      if (_solidInputsSame(prevBuildings, buildings)) {
        _prevBuildingsRef.current = buildings;
        return;
      }
      console.warn('[SOLID_SYNC] buildings変更検出 → solids再生成', { blocked: false, bldCount: buildings?.length });
      _prevBuildingsRef.current = buildings;
      _solidSyncBlockedForRef.current = null;

      // 削り出し済みSolid (face数 > 期待値) は再生成せずzTop/zBottomデルタだけ適用
      // face.holesは廃止 — 全面が単純クローズドポリゴンとして定義される
      const _isModified = (solid, blk) => {
        if (!solid || !blk?.points) return false;
        // 【掃引の立体は必ず作り直す・2026-10-14 実測】面の数が points+2 でないことを
        //   「削り出し済み」の印にしているが、掃引（回転体・らせん・通りに沿わせた物）は
        //   もともと面が多いので**必ず誤判定**になる。そのため記録を変えても形が変わらず、
        //   「回す軸を動かしても直径が変わらない」「回す角度を変えても形が変わらない」が出た。
        //   掃引は記録（blk.sweep）から完全に組み立て直せるので保持しない。
        //   【陽性対照】window.__SOLID_REBUILD_SWEEP = false で従来＝保持
        if (blk.sweep && !(typeof window !== 'undefined'
            && window.__SOLID_REBUILD_SWEEP === false)) return false;
        const expected = blk.points.length + 2;
        return solid.faces.length !== expected;
      };
      const _applyZDelta = (solid, oldZT, newZT, oldZB, newZB) => {
        const Z_TOL = 0.05;
        const _xform = (v) => {
          if (Math.abs(v.z - oldZT) < Z_TOL) return { ...v, z: newZT };
          if (Math.abs(v.z - oldZB) < Z_TOL) return { ...v, z: newZB };
          return { ...v };
        };
        const newFaces = solid.faces.map(f => ({
          ...f,
          vertices: f.vertices.map(_xform),
          ...(f.holes ? { holes: f.holes.map(hole => hole.map(_xform)) } : {}),
        }));
        return { ...solid, faces: newFaces };
      };

      const newSolids = [];
      buildings.forEach(bld => {
        bld.blocks.forEach((blk, bi) => {
          const expectedId = bld.id + '_' + bi;
          const existing = solidsRef.current.find(s => s.id === expectedId);
          const prevBlk = prevBuildings?.find(b => b.id === bld.id)?.blocks?.[bi];
          if (existing && prevBlk && _isModified(existing, blk)) {
            const oldZT = prevBlk.zTop != null ? prevBlk.zTop : 40;
            const newZT = blk.zTop != null ? blk.zTop : 40;
            const oldZB = prevBlk.zBottom || 0;
            const newZB = blk.zBottom || 0;
            if (Math.abs(oldZT - newZT) > 1e-4 || Math.abs(oldZB - newZB) > 1e-4) {
              console.warn('[SOLID_SYNC] 削り出し済みSolid保持 → zデルタ適用', {
                solidId: existing.id, oldZT, newZT, oldZB, newZB, faceCount: existing.faces.length,
              });
              newSolids.push(_applyZDelta(existing, oldZT, newZT, oldZB, newZB));
            } else {
              // z変更なし → そのまま保持
              newSolids.push(existing);
            }
          } else {
            // 新規 or 単純箱: 通常通り再生成
            // 【2026-09-23】増築棟と親をつなぐ穴を渡す（共通述語 sharedWallOpeningsForBlock）
            // 【2026-10-03】押し出しと掃引（らせん・斜路）の呼び分けは blockSolidOf だけが持つ。
            //   ここで直に blockToSolid を呼ぶと、掃引の建屋が3次元図に出ない
            // 【2026-10-03】並べた部材（螺旋階段の段板など）は1ブロックから複数の立体になる
            blockSolidsOf(bld, blk, bi).forEach(s2 => newSolids.push(s2));
          }
        });
      });
      setSolids(newSolids);
    }
  });
  // CesiumMapから呼べるSolid直接更新関数（buildings同期をブロックする）
  const setSolidsDirect = useCallback((newSolids) => {
    _solidSyncBlockedForRef.current = buildings;
    setSolids(newSolids);
  }, [buildings]);

  // ══ CSG立体（bodies）・2026-09-26 ══
  // 【ここに置く理由】下の undo/redo が bodies も見るので、**宣言が先**でないと
  //   依存配列を読む時点で初期化前になる（const は宣言前に読むと落ちる）。
  const [bodies, setBodies] = useState([]);       // [{id,label,color,ops:[...]}]
  // 【地面に塗る面・2026-11-24 ユーザー裁定「道の厚みは求めていない」】
  //   立体（blocks）でなく、**地面の上に色を置くだけ**の面。いまの使い手は地図から取り込んだ道路。
   //   「道路」という名前にしない（次に水面・敷地・緑地が来ても同じ入れ物で足りる＝SPEC §1）。
   //   形は **中心線＋幅**（線を太らせた輪は持たない）。帯は描くときに地面の起伏に乗せて作るので、
   //   自己交差を避けるために切る必要がなく、ユーザー報告の「帯が切れる」が構造的に起きない。
  //   [{ id, key, 種別, 中心線:[{x,y}グリッド], 幅m, color }]
  const [groundAreas, setGroundAreas] = useState([]);

  // === 建物undo/redo ===
  // mousedown〜mouseupを1操作としてカウント。ドラッグ中の連続setBuildings→1undo
  // 【2026-09-29】立体（bodies）も同じ1つの stack で戻す。別の stack にすると
  //   Ctrl+Z の順序が2つに割れる（Codex監査）。csgSolids は bodies から作り直すので控えない。
  const bldUndoRef = useRef([]);
  const bldRedoRef = useRef([]);
  const bldPrevRef = useRef({ bld: buildings, bodies: [] });
  const bldSnapRef = useRef(null);
  const bldTimerRef = useRef(null);
  const bldIsUndoRedoRef = useRef(false);
  const bldMouseUpRef = useRef(null);   // mouseupリスナー解除用
  const buildingsRef = useRef(buildings);
  buildingsRef.current = buildings;

  // undo/redoエントリ: { bld: buildings[], sol: solids[]|null }
  // sol=null → buildings復元時にsolidsを自動再生成, sol有り → solidsも復元
  const _undoLog = (tag, extra) => {
    const _entryInfo = (e) => e?.bld ? `${e.bld.length}bld${e.sol ? '+sol' : ''}` : `${e?.length}(legacy)`;
    console.warn(`[UNDO_${tag}]`, {
      ...extra,
      undoStack: bldUndoRef.current.map(_entryInfo),
      redoStack: bldRedoRef.current.map(_entryInfo),
      current: buildingsRef.current?.length,
    });
  };
  // 【控えに「地面に塗る面」も入れる・2026-11-24】別の山にすると Ctrl+Z の順序が割れる
  //   （bodies を足したときと同じ作法）。足す所は5つ: ここ・下の効果・bldUndo・bldRedo・bldPushUndo
  const _makeEntry = (bld, sol, bodies2, areas2) => ({
    bld: JSON.parse(JSON.stringify(bld)),
    sol: sol ? JSON.parse(JSON.stringify(sol)) : null,
    bodies: bodies2 ? JSON.parse(JSON.stringify(bodies2)) : [],
    areas: areas2 ? JSON.parse(JSON.stringify(areas2)) : [],
  });
  const _restoreEntry = (entry) => {
    // legacy形式(配列)とnew形式({bld,sol})の両方に対応
    if (Array.isArray(entry)) return { bld: entry, sol: null };
    return entry;
  };
  const bldCommitSnap = useCallback(() => {
    if (bldSnapRef.current !== null) {
      bldUndoRef.current.push(bldSnapRef.current);
      if (bldUndoRef.current.length > 100) bldUndoRef.current.shift();
      bldSnapRef.current = null;
    }
    if (bldMouseUpRef.current) {
      window.removeEventListener('mouseup', bldMouseUpRef.current);
      bldMouseUpRef.current = null;
    }
    clearTimeout(bldTimerRef.current);
  }, []);

  useEffect(() => {
    const prev = bldPrevRef.current;
    bldPrevRef.current = { bld: buildings, bodies, areas: groundAreas };
    if (bldIsUndoRedoRef.current) {
      bldIsUndoRedoRef.current = false;
      bldSnapRef.current = null;
      return;
    }
    if (prev.bld === buildings && prev.bodies === bodies && prev.areas === groundAreas) return;
    // バースト最初の変更: 変更前の状態を保存（solids・立体も含む → undoで完全復元）
    if (bldSnapRef.current === null) {
      bldSnapRef.current = _makeEntry(prev.bld, solidsRef.current, prev.bodies, prev.areas);
      const onUp = () => {
        bldMouseUpRef.current = null;
        bldTimerRef.current = setTimeout(() => bldCommitSnap(), 50);
      };
      bldMouseUpRef.current = onUp;
      window.addEventListener('mouseup', onUp, { once: true });
      clearTimeout(bldTimerRef.current);
      bldTimerRef.current = setTimeout(() => bldCommitSnap(), 200);
    } else {
      clearTimeout(bldTimerRef.current);
      bldTimerRef.current = setTimeout(() => bldCommitSnap(), 200);
    }
    bldRedoRef.current = [];
  }, [buildings, bodies, groundAreas, bldCommitSnap]);

  const bldUndo = useCallback(() => {
    bldCommitSnap();
    if (bldUndoRef.current.length === 0) { _undoLog('UNDO_EMPTY', {}); return; }
    const raw = bldUndoRef.current.pop();
    const entry = _restoreEntry(raw);
    // 現在の状態（solids・立体を含む）をredoに保存
    bldRedoRef.current.push(_makeEntry(buildingsRef.current, solidsRef.current, bodiesRef.current, groundAreasRef.current));
    _undoLog('UNDO', { restored: `${entry.bld.length}bld${entry.sol ? '+sol' : ''}` });
    bldIsUndoRedoRef.current = true;
    _solidSyncBlockedForRef.current = null;
    setBuildings(entry.bld);
    // 立体も戻す。csgSolids は bodies から作り直されるので控えていない
    setBodies(entry.bodies || []);
    setGroundAreas(entry.areas || []);
    // 【二重記録を防ぐ】戻した値を「前の状態」にしておく。効果が2回走っても差が無いので記録されない
    bldPrevRef.current = { bld: entry.bld, bodies: entry.bodies || [], areas: entry.areas || [] };
    if (entry.sol) {
      // solidsも復元 → SOLID_SYNCの再生成を防ぐ
      _solidSyncBlockedForRef.current = entry.bld;
      _prevBuildingsRef.current = entry.bld;
      setSolids(entry.sol);
    }
  }, [bldCommitSnap]);

  const bldRedo = useCallback(() => {
    bldCommitSnap();
    if (bldRedoRef.current.length === 0) { _undoLog('REDO_EMPTY', {}); return; }
    const raw = bldRedoRef.current.pop();
    const entry = _restoreEntry(raw);
    // 現在の状態（solids・立体を含む）をundoに保存
    bldUndoRef.current.push(_makeEntry(buildingsRef.current, solidsRef.current, bodiesRef.current, groundAreasRef.current));
    _undoLog('REDO', { restored: `${entry.bld.length}bld${entry.sol ? '+sol' : ''}` });
    bldIsUndoRedoRef.current = true;
    _solidSyncBlockedForRef.current = null;
    setBuildings(entry.bld);
    setBodies(entry.bodies || []);
    setGroundAreas(entry.areas || []);
    bldPrevRef.current = { bld: entry.bld, bodies: entry.bodies || [], areas: entry.areas || [] };
    if (entry.sol) {
      _solidSyncBlockedForRef.current = entry.bld;
      _prevBuildingsRef.current = entry.bld;
      setSolids(entry.sol);
    }
  }, [bldCommitSnap]);

  // 削り出し等の操作前にundo snapshotを明示的に保存する関数（solids・立体つき）
  const bldPushUndo = useCallback(() => {
    bldCommitSnap();
    bldUndoRef.current.push(_makeEntry(buildingsRef.current, solidsRef.current, bodiesRef.current, groundAreasRef.current));
    if (bldUndoRef.current.length > 100) bldUndoRef.current.shift();
    bldRedoRef.current = [];
    _undoLog('PUSH_CARVE', {});
  }, [bldCommitSnap]);

  // ===== 階（建物内部 Phase A・buildingCore.js）=====
  // 階のCRUDは全て setBuildings 経由 → 上のuseEffectの自動スナップショットにより
  // 最小粒度Undo（spec 7.8）がそのまま成立する
  const [floorFollow, setFloorFollow] = useState(true); // 構造体変形に階外形を追従させるか（spec 7.5）
  // ══ 形を持つもの（ホスト）── 2026-11-05 ══
  // 階・仕切り・扉・機器は「形を持つもの」に付く。建屋（buildings）と立体（bodies）で
  // 関数を書き分けると**片方にしか機能が付かない**。それが「立体に階が作れない」の
  // 発生源だったので、入口は1つにして、どちらの台帳を書くかだけを中で分ける。
  const _ホストを探す = useCallback((hostId) => {
    const b = (buildingsRef.current || []).find(x => x && x.id === hostId);
    if (b) return { host: b, 立体: false };
    const d = (bodiesRef.current || []).find(x => x && x.id === hostId);
    if (d) return { host: d, 立体: true };
    return null;
  }, []);
  const _ホストを書く = useCallback((hostId, 立体, fn) => {
    if (立体) setBodies(prev => prev.map(x => x.id === hostId ? fn(x) : x));
    else setBuildings(prev => prev.map(x => x.id === hostId ? fn(x) : x));
  }, []);
  // 【立体の面を読む口を渡す】buildingCore は App の state を知らないので、
  //   評価済みの立体を引く関数を1回だけ登録する（ref を読むので登録は1回でよい）。
  //   登録が無いと bcHostLayers は立体で null（＝まだ計算していない）を返す。
  useEffect(() => {
    if (typeof bcSetBodySolidReader !== 'function') return;
    bcSetBodySolidReader((bodyId) =>
      (csgSolidsRef.current || []).find(s2 => s2 && s2.id === bodyId) || null);
    return () => { try { bcSetBodySolidReader(null); } catch (e) {} };
  }, []);

  const onAddFloor = useCallback((hostId, levelZ, heightM) => {
    const h = _ホストを探す(hostId);
    if (!h) return '構造体が見つかりません';
    const f = bcNewFloor(levelZ, { heightM });
    const v = bcValidateFloor(h.host, f);
    if (!v.ok) return v.errors.join(' / ');
    _ホストを書く(hostId, h.立体, x => ({ ...x, floors: [...(x.floors || []), f] }));
    return null;
  }, [_ホストを探す, _ホストを書く]);
  const onUpdateFloor = useCallback((hostId, floorId, patch) => {
    const h = _ホストを探す(hostId);
    if (!h) return '構造体が見つかりません';
    const cur = (h.host.floors || []).find(f => f.id === floorId);
    if (!cur) return '階が見つかりません';
    const nf = { ...cur, ...patch };
    const v = bcValidateFloor(h.host, nf);
    if (!v.ok) return v.errors.join(' / ');
    _ホストを書く(hostId, h.立体, x => ({ ...x,
      floors: (x.floors || []).map(f => f.id === floorId ? nf : f) }));
    return null;
  }, []);
  const onDeleteFloor = useCallback((hostId, floorId) => {
    const h = _ホストを探す(hostId);
    if (!h) return;
    _ホストを書く(hostId, h.立体, x => ({ ...x,
      floors: (x.floors || []).filter(f => f.id !== floorId) }));
  }, [_ホストを探す, _ホストを書く]);
  // 追従OFFへ切替: いまの外形をスナップショットして固定（単一ポリゴンのときのみ。
  // 複数blockまたぎの階は固定できないため継承のまま）／ONへ切替: 継承(null)に戻す
  const onToggleFloorFollow = useCallback(() => {
    setFloorFollow(prev => {
      const next = !prev;
      setBuildings(bp => bp.map(b => ({
        ...b,
        floors: (b.floors || []).map(f => {
          // 【重要】ユーザーが手で編集したカスタム床(outlineCustom)は追従トグルで消さない。
          // 消してしまうと「床を作り込んだ後に追従を切り替えたら黙って消える」ことになる（監査指摘）
          if (f.outlineCustom) return f;
          if (next) return { ...f, outline: null };
          const polys = bcFloorOutlines(b, f);
          return polys.length === 1 ? { ...f, outline: polys[0] } : f;
        }),
      })));
      return next;
    });
  }, []);
  // ===== 床のカスタム外形（建物の断面すべてが部屋とは限らないため） =====
  // outlineCustom=true を立てて「ユーザーが作った床」と「追従OFFの自動スナップショット」を区別する
  const onSetFloorOutline = useCallback((buildingId, floorId, points) => {
    if (points && points.length < 3) return '床は3点以上必要です';
    setBuildings(prev => prev.map(b => b.id !== buildingId ? b : {
      ...b,
      floors: (b.floors || []).map(f => f.id !== floorId ? f
        : (points ? { ...f, outline: points, outlineCustom: true }
                  : { ...f, outline: null, outlineCustom: false })), // null=構造体断面の継承に戻す
    }));
    return null;
  }, []);
  // 床を編集した結果、外に出てしまった仕切りを列挙する（自動削除はしない＝ユーザーが決める）
  const getPartitionsOutsideFloor = useCallback((buildingId, floorId) => {
    const b = (buildingsRef.current || []).find(x => x.id === buildingId);
    const f = b && (b.floors || []).find(x => x.id === floorId);
    if (!f) return [];
    return (f.partitions || []).filter(p => !bcValidatePartition(b, f, p).ok).map(p => p.id);
  }, []);

  // ══ 立体（CSGボディ）の編集の入口 ・2026-09-27 Codex監査済み ══
  // 【なぜここに集めるか】ops は「作り方の履歴」で、**上から順にそれまでの結果へ**効く。
  //   書き換える場所が散ると、順番の意味が壊れたことに気づけない。
  //   setBodies を直に呼ぶのはこの5つだけにする。
  // 【単位】ops の寸法・位置はすべてメートル（csgCore.js の約束）。
  const _patchBody = useCallback((bodyId, fn) => {
    setBodies(prev => prev.map(b => (b.id === bodyId ? fn(b) : b)));
  }, []);
  const onUpdateBody = useCallback((bodyId, patch) => {
    if (!bodyId || !patch) return;
    _patchBody(bodyId, b => ({ ...b, ...patch }));
  }, [_patchBody]);
  const onDeleteBody = useCallback((bodyId) => {
    setBodies(prev => prev.filter(b => b.id !== bodyId));
    // 消したものを選んだままにしない（選択解除の入口は1本＝選択を持つ側で外す）
    setSelBldPart(s => (s && s.kind === 'body' && s.id === bodyId ? null : s));
  }, []);
  const onUpdateBodyOp = useCallback((bodyId, opIdx, patch) => {
    if (!bodyId || !patch) return;
    _patchBody(bodyId, b => ({ ...b, ops: (b.ops || []).map((o, i) => (i === opIdx ? { ...o, ...patch } : o)) }));
  }, [_patchBody]);
  // 段の入れ替え。**順番が形そのもの**なので、これは見た目でなく形の編集
  const onMoveBodyOp = useCallback((bodyId, opIdx, dir) => {
    _patchBody(bodyId, b => {
      const ops = [...(b.ops || [])];
      const j = opIdx + dir;
      if (j < 0 || j >= ops.length) return b;
      const t = ops[opIdx]; ops[opIdx] = ops[j]; ops[j] = t;
      return { ...b, ops };
    });
  }, [_patchBody]);
  const onDeleteBodyOp = useCallback((bodyId, opIdx) => {
    _patchBody(bodyId, b => {
      const ops = (b.ops || []).filter((o, i) => i !== opIdx);
      if (!ops.length) return b;          // 全部消して空の立体にはしない
      // 1段目は土台なのでモードを持たない（残った先頭のモードは意味を失う）
      if (ops[0] && ops[0].mode) ops[0] = { ...ops[0], mode: 'union' };
      return { ...b, ops };
    });
  }, [_patchBody]);
  // ══ 壁にする ・2026-09-30 Codex監査済み ══
  // 【重ねがけを防ぐ】**壁の段を外した ops** から毎回作り直して置き換える。
  //   末尾に足すだけだと、2回押したときに「壁にした形」をさらに縮めてしまう。
  //   厚みを変えたいときも同じ道を通るので、あとから何度でも直せる。
  // 【できないときは黙らない】理由を持ち帰って画面に出す。
  const [wallifyMsg, setWallifyMsg] = useState(null);   // { bodyId, 理由 } | null
  const onWallifyBody = useCallback(async (bodyId, opts) => {
    const b = (bodiesRef.current || []).find(x => x.id === bodyId);
    if (!b) return;
    const base = (b.ops || []).filter(op => op.tool !== 'wallify');
    if (!base.length) { setWallifyMsg({ bodyId, 理由: '元の形がありません' }); return; }
    if (typeof csgWallifyOp !== 'function') { setWallifyMsg({ bodyId, 理由: '未対応です' }); return; }
    const r = await csgWallifyOp(base, opts);
    if (!r || !r.ok) { setWallifyMsg({ bodyId, 理由: (r && r.理由) || '壁にできません' }); return; }
    setWallifyMsg(null);
    setBodies(prev => prev.map(x => x.id !== bodyId ? x : { ...x, ops: [...base, r.op] }));
  }, []);
  // 壁をやめる（壁の段だけ外す）
  const onUnwallifyBody = useCallback((bodyId) => {
    setWallifyMsg(null);
    setBodies(prev => prev.map(x => x.id !== bodyId ? x
      : { ...x, ops: (x.ops || []).filter(op => op.tool !== 'wallify') }));
  }, []);

  // 新しい段は「今の立体の真ん中」に出す（原点に出ると画面の外で見つけられない）
  const onAddBodyOp = useCallback((bodyId, kind, mode) => {
    const mpp = (typeof METERS_PER_PX === 'number' && METERS_PER_PX > 0) ? METERS_PER_PX : 0.1;
    const sol = (csgSolidsRef.current || []).find(s2 => s2.id === bodyId);
    const bb = sol && sol.bbox;
    const c = bb ? { x: (bb.minX + bb.maxX) / 2 * mpp, y: (bb.minY + bb.maxY) / 2 * mpp,
                     z: (bb.minZ + bb.maxZ) / 2 }
                 : { x: 0, y: 0, z: 0 };
    const mk = (typeof BE_KINDS !== 'undefined') ? BE_KINDS.find(k => k.kind === kind) : null;
    if (!mk) return;
    const op = { ...mk.作る(c), mode: mode || 'union' };
    _patchBody(bodyId, b => ({ ...b, ops: [...(b.ops || []), op] }));
  }, [_patchBody]);

  // ══ 平面図で描いた形から「建屋」か「立体」を作る唯一の入口 ・2026-09-28 Codex監査済み ══
  // 【なぜ1本にするか】作る場所が4つある（矩形・円・多角形の始点クリック・多角形のダブルクリック）。
  //   「建屋か立体か」を4か所に書くと必ずどこかが漏れる。
  // 【建屋と立体の違い】建屋＝階・仕切り・扉・部屋認識を持てる／立体＝押し引き・結合・くり抜きができる。
  //   取り違えたら作り直す（相互の変換は持たない。持つと仕様が倍になる・Codex判定）。
  // shape は円のときだけ渡す（半径を後から直すのに使う。立体では使わない）。
  // extra: ブロックに足す記録（pattern＝並べる／sweep＝経路に沿わせる／zTop の上書き）。
  //   _label を入れると建屋の名前になる（「螺旋階段1」など）
  // opts.forceBuilding … 立体（CSG）ではなく必ず建屋として作る。
  //   掃引はブーリアンの履歴ではないので、立体側へ流すと形が落ちる（2026-10-04）
  const finishBldOutline = (points, shape, extra, opts) => {
    if (!points || points.length < 3) return;
    if (bldDrawTarget === 'body' && !(opts && opts.forceBuilding)) {
      const ops = (typeof csgPlanOutlineOps === 'function')
        ? csgPlanOutlineOps(points, NEW_BLD_H_M, 0) : null;
      if (!ops) return;
      bodyCounter.current++;
      const id = 'body' + bodyCounter.current;
      setBodies(prev => [...prev, {
        id, label: '立体' + bodyCounter.current,
        color: BLD_COLORS[(bodyCounter.current - 1) % BLD_COLORS.length], ops,
        floors: [],   // 【2026-11-05】立体にも階が付く（建屋と同じ形で持つ）
      }]);
      _selectBldPart({ kind: 'body', id });     // 作ったものを選ぶ（建屋側は選ばない）
      return id;        // 作り直しのために id を返す（2026-10-12）
    }
    bldCounter.current++;
    const newId = 'bld' + bldCounter.current;
    const _extra = Object.assign({}, extra); const _nm = _extra._label || '建屋'; delete _extra._label;
    setBuildings(prev => [...prev, {
      id: newId, label: _nm + bldCounter.current,
      color: BLD_COLORS[(bldCounter.current - 1) % BLD_COLORS.length],
      blocks: [{ points, zBottom: 0, zTop: NEW_BLD_H_M, ...(shape ? { shape } : {}), ..._extra }],
    }]);
    setSelectedBld(newId);
    return newId;       // 作り直しのために id を返す（2026-10-12）
  };
  // ブロックの記録から、建屋に入れる形だけを取り出す（名前は建屋側が持つ）
  const _ブロックだけ = (b) => { const c = Object.assign({}, b); delete c._label; return c; };
  // 【ブロック列から建屋を1つ作る・2026-10-18】
  //   回すで軸が輪郭の中を通ると、軸で割った**2つ**のブロックになる。
  //   1個でも2個でもここを通す（入口を分けると、足した方だけが新しい仕組みを知らなくなる）。
  const finishBldOutlineBlocks = (blks) => {
    if (!blks || !blks.length) return null;
    bldCounter.current++;
    const newId = 'bld' + bldCounter.current;
    const 名 = blks[0]._label || '建屋';
    setBuildings(prev => [...prev, {
      id: newId, label: 名 + bldCounter.current,
      color: BLD_COLORS[(bldCounter.current - 1) % BLD_COLORS.length],
      blocks: blks.map(_ブロックだけ),
    }]);
    setSelectedBld(newId);
    return newId;
  };

  // ══ 地図から建物をまとめて取り込む・2026-11-23 ══
  // 【1件ずつ finishBldOutline を呼ばない】あれは1件ごとに setBuildings して、作った物を選ぶ。
  //   数百件のループで呼ぶと作り直しが数百回走る。ここは控え(bldPushUndo)1回・setBuildings 1回。
  // 【建物1件＝建屋1つ・ブロック1つ】ブロックは「同じ建屋の高さ違いの棟」で、移動も削除も親子
  //   単位になる。別々の建物を1つの建屋の blocks に入れてはいけない。
  // 【印は `_` 始まり】flattenBuildings はフィールドを明示選択するが、`_` 始まりは機械的に運ぶ。
  //   素の名前（source など）で足すと平らにした時点で落ちる（CLAUDE.md に2回踏んだ記録）。
  // 【高さは実測ではない】ベクトルタイルに高さは入っていない（実測で確認）。仮の値を置き、
  //   `_src.高さ未確定` を立てる。建物エディタで高さを打ったら外す。
  const _取込の印 = (blk) => !!(blk && blk._src && blk._src.由来);   // 取り込み元を問わず「地図から来た建物」
  // 点の列（グリッド座標）が乗る地面の高さ（**メートル**）。地面が無ければ { 乗せた: false }。
  //   旗 window.__GSI_BLD_ON_GROUND = false で従来（基準面 0 に置く）＝陽性対照。
  const _gsiGroundZ = (pts, 地形) => {
    if (typeof window !== 'undefined' && window.__GSI_BLD_ON_GROUND === false) return { 乗せた: false, z: 0 };
    const _t = 地形 || terrainDraw;
    if (!_t || typeof terrainZAt !== 'function' || !Array.isArray(pts) || !pts.length) return { 乗せた: false, z: 0 };
    const _div = uiSettingValue(uiSettings, 'terrainGrid');
    let 最小 = Infinity;
    for (const q of pts) {
      // mToPx = 1 → メートルで返る。**強調は掛けない**（ユーザー裁定 2026-11-26
      //   「強調倍率を2以上にした時は建物は関係なく地面だけ高くなる」）。
      //   建屋の z はメートルで、描く側の _bldZPx には強調が掛からない。ここで掛けると二重になる。
      const v = terrainZAt(_t, TW, TH, q.x, q.y, 1, 1, _div);
      if (!Number.isFinite(v)) return { 乗せた: false, z: 0 };   // 欠測は乗せない（fail-closed）
      if (v < 最小) 最小 = v;
    }
    return Number.isFinite(最小) ? { 乗せた: true, z: 最小 } : { 乗せた: false, z: 0 };
  };
  // 【取り込み済みの建物を地面の上に乗せ直す・2026-11-26 ユーザー指示（類似①）】
  //   「地面を作るときにすでにある建物を地面の上に移動するか聞くようにしろ」
   //   ★今の zBottom が記録（_src.GL）と一致する物だけ書き換える＝**手で直した高さは触らない**（監査の条件）。
   //   ★地面を作った直後は state の terrainDraw がまだ古いので、**新しい地形を引数で**受ける。
  const _liftBuildingsToGround = (地形, { 聞く } = {}) => {
    const 今 = buildingsRef.current || [];
    // 動かす対象を数える（取り込んだ物で、手で直していない物）
    const _対象 = (b, bl) => {
      if (!bl || !bl._src || !bl.points || !bl.points.length) return null;
      const 旧GL = (bl._src.GL == null) ? 0 : bl._src.GL;
      if (Math.abs((bl.zBottom || 0) - 旧GL) > 1e-6) return null;   // 手で直した＝触らない
      const g = _gsiGroundZ(bl.points, 地形);
      if (!g.乗せた) return null;
      if (Math.abs(g.z - 旧GL) < 1e-6) return null;                  // もう乗っている
      return g.z;
    };
    let 数 = 0;
    for (const b of 今) for (const bl of (b.blocks || [])) if (_対象(b, bl) != null) 数++;
    if (!数) return 0;
    if (聞く && typeof window !== 'undefined' && typeof window.confirm === 'function') {
      const ok = window.confirm('地面ができました。取り込んだ建物 ' + 数 + ' 件を地面の上に乗せますか？\n'
        + '（手で高さを変えた建物は動かしません）');
      if (!ok) return 0;
    }
    bldPushUndo();
    setBuildings(prev => prev.map(b => ({ ...b, blocks: (b.blocks || []).map(bl => {
      const z = _対象(b, bl);
      if (z == null) return bl;
      const 高 = (bl._src && bl._src.高さm != null) ? bl._src.高さm : ((bl.zTop || 0) - (bl.zBottom || 0));
      return { ...bl, zBottom: z, zTop: z + 高, _src: { ...bl._src, GL: z } };
    }) })));
    console.log('[地面] 取り込んだ建物 ' + 数 + ' 件を地面の上に乗せた');
    return 数;
  };
  const importMapBuildings = (items) => {
    const 空 = { 足した: 0, 重複: 0, 重なり: 0 };
    if (!items || !items.length) return 空;
    const 今 = buildingsRef.current || [];
    const 既 = new Set();
    for (const b of 今) for (const blk of (b.blocks || [])) if (blk && blk._src && blk._src.key) 既.add(blk._src.key);
    for (const a of (groundAreasRef.current || [])) if (a && a.key) 既.add(a.key);
    // 手で作った建屋（取り込み以外）の外接。そこに重なる建物は足さない
    const 手の枠 = [];
    for (const b of 今) for (const blk of (b.blocks || [])) {
      if (_取込の印(blk) || !Array.isArray(blk.points) || !blk.points.length) continue;
      const xs = blk.points.map(q => q.x), ys = blk.points.map(q => q.y);
      手の枠.push({ x0: Math.min(...xs), x1: Math.max(...xs), y0: Math.min(...ys), y1: Math.max(...ys) });
    }
    let 重複 = 0, 重なり = 0, 交差 = 0;
    const 新 = [];
    // 地面の高さに乗せた建物（下で「乗せますか？」と聞き、いいえなら基準面 0 に戻す）
    const 乗せた棟 = [];
    // 【塗る面（道路など）を分ける・2026-11-24】立体にせず「地面に塗る面」として持つ。
    //   振り分けは **it.塗る**（gsiTiles.js の GSI_IMPORT_LAYERS が渡す）。
    //   ここに `if (種別 === "道路")` を書かない＝レイヤを増やしてもここは変えない（SPEC §1）。
    const 新面 = [];
    let c = bldCounter.current;
    for (const it of items) {
      if (it.塗る) {
        // 【形（輪）で来る面・2026-11-27】交差点の角（隅切り）など、中心線でなく輪郭で持つ面
        if (Array.isArray(it.輪) && it.輪.length >= 3) {
          if (既.has(it.key)) { 重複++; continue; }
          既.add(it.key);
          // 【島（穴）・2026-11-28】道路の中の島・池の中の島は 穴 で運ぶ（描くときに抜く）
          const _穴 = Array.isArray(it.穴) ? it.穴.filter(Q => Array.isArray(Q) && Q.length >= 3) : [];
          新面.push({ id: 'ga' + (++c), key: it.key, 種別: it.種別, 輪: it.輪, ...(_穴.length ? { 穴: _穴 } : {}), color: it.color || "#9CA3AF",
            _src: Object.assign({ 由来: "gsi-bvmap", key: it.key, 種別: it.種別 }, it.srcAdd || {}) });
          continue;
        }
        if (!Array.isArray(it.中心線) || it.中心線.length < 2) continue;
        if (既.has(it.key)) { 重複++; continue; }
        既.add(it.key);
        新面.push({ id: 'ga' + (++c), key: it.key, 種別: it.種別,
          中心線: it.中心線, 幅m: it.幅m || 2, color: it.color || "#9CA3AF",
          // 【左右の半幅（道路の縁の線から実測）・2026-11-27】中心線の各点ぶん。無ければ 幅m の一定幅
          ...(Array.isArray(it.幅左m) && Array.isArray(it.幅右m) ? { 幅左m: it.幅左m, 幅右m: it.幅右m } : {}),
          _src: Object.assign({ 由来: "gsi-bvmap", key: it.key, ftCode: it.ftCode, 種別: it.種別 }, it.srcAdd || {}) });
        continue;
      }
      const pts = it.points;
      if (!pts || pts.length < 3) continue;
      if (既.has(it.key)) { 重複++; continue; }
      let gx = 0, gy = 0; for (const q of pts) { gx += q.x; gy += q.y; }
      gx /= pts.length; gy /= pts.length;
      // 【手で作った建屋と重なるものは足さない・規則を直した 2026-11-24】
      //   旧: 重心が枠内なら捨てる → 長い道路の重心がたまたま建屋の中に来ると道路が黙って消えた。
      //   新: **外接矩形がその枠にすっぽり収まるとき**だけ捨てる（＝二重に足したものだけを捨てる）。
      //   旗 window.__IMPORT_SKIP_BY_BBOX = false で従来（重心で判定）＝陽性対照。
      const _外 = { x0: Math.min(...pts.map(q => q.x)), x1: Math.max(...pts.map(q => q.x)),
                    y0: Math.min(...pts.map(q => q.y)), y1: Math.max(...pts.map(q => q.y)) };
      const _枠で捨てる = (typeof window !== 'undefined' && window.__IMPORT_SKIP_BY_BBOX === false)
        ? 手の枠.some(r => gx >= r.x0 && gx <= r.x1 && gy >= r.y0 && gy <= r.y1)
        : 手の枠.some(r => _外.x0 >= r.x0 && _外.x1 <= r.x1 && _外.y0 >= r.y0 && _外.y1 <= r.y1);
      if (_枠で捨てる) { 重なり++; continue; }
      // 【自己交差した輪は足さない・2026-11-24 Codex監査の条件】
      //   面は穴を持てない（SPEC §3.7）。自己交差すると blockToSolid が符号付き面積で向きを決めるので
      //   壁の法線が一部内向きになり、上面の塗りも乱れる。検査の式は csgCore の csgPolyContour に
      //   既にあるので二重に書かず、ここで呼ぶ（Zenodo の取り込みも同時に守れる）。
      if (typeof csgPolyContour === 'function') {
        // ★ csgPolyContour は **[x, y] の配列**を受ける（{x,y} を渡すと必ず null ＝全部捨てる）
        const _c = csgPolyContour(pts.map(q => [q.x, q.y]));
        if (!_c) { 交差++; continue; }
      }
      既.add(it.key);
      // 形の見分けは solidModel の純関数1つ（円かどうかをここで判定しない）
      // 【データが「タンク」と言っているものは円柱にする・2026-11-23 ユーザー指示】
      //   地図の記号コード 4302＝タンク。点列が多少いびつでも（測量の誤差・タイルの切れ）
      //   円柱で間違いない。形から推し量るより、**データの意味**を信じる。
      // 【範囲で切り取った建物は形のまま・2026-11-28】切り口のあるタンクを円柱に作り直すと、切った所がまた丸く戻って
      //   範囲の外へはみ出す（実測: タンク1件で頂点11個が範囲の外）。切った足元の形をそのまま押し出す。
      const _切った = !!(it.srcAdd && it.srcAdd.範囲で切った);
      let shape = (!_切った && typeof shapeFromOutline === "function") ? shapeFromOutline(pts) : null;
      if (!shape && !_切った && it.種別 === "タンク" && typeof circleFromOutline === "function") {
        shape = circleFromOutline(pts);
      }
      const 点 = (shape && typeof blockShapePoints === "function") ? blockShapePoints(shape) : pts;
      c++;
      // 【実データの高さがあれば使う・2026-11-23】Zenodo の建物データは Height（m）を持つ。
      //   国土地理院のベクトルタイルには高さが無いので、そちらは仮の値のまま。
      //   どちらから来たかは _src.由来 に残す（取り込み元ごとに分岐を増やさない）。
      const 高 = (typeof it.height === "number" && it.height > 0) ? it.height : NEW_BLD_H_M;
      // 【地面の高さに乗せる（GL補正）・2026-11-26 ユーザー報告「すべて地下に建物があるかのよう」】
      //   地面を作っていればその高さに置く。作っていなければ従来どおり 0（fail-closed）。
      //   ★見るのは **terrainDraw**（海抜基準・地面の上下を反映した、面と道路の塗りが見るのと同じ物）。
      //   ★強調倍率は**掛けない**（_gsiGroundZ の中のコメント＝ユーザー裁定 2026-11-26 を見よ）。
      //   ★サンプルは**頂点の最小**（重心は L字・凹形で建物の外に落ちる＝監査の指摘。
      //     最小なら斜面で食い込むが浮かない。浮いて隙間が見えるより自然）。
      //   ★mToPx に 1 を渡す＝**メートル**で返る（建屋の z はメートル。換算を増やさない）。
      const _GL = _gsiGroundZ(点);
      const 高底 = _GL.乗せた ? _GL.z : 0;
      const blk = {
        points: 点, zBottom: 高底, zTop: 高底 + 高,
        _src: { 由来: it.由来 || (it.ftCode != null ? "gsi-bvmap" : "zenodo"), key: it.key,
                // 乗せた標高（m）と高さ。後から地面を作り直したとき「手で直していないか」を見分ける
                GL: _GL.乗せた ? 高底 : null, 高さm: 高,
                ftCode: it.ftCode, 種別: it.種別, 高さ未確定: !(typeof it.height === "number" && it.height > 0),
                // 【points は結果、意図は別に持つ・SPEC §3.9】道路の中心線と幅員区分を残す。
                //   捨てると幅を直すときに輪郭から逆算することになる。
                //   平面図が掃引を描けるようになったら、ここから makeSweptBlock で作り直せる。
                ...(it.srcAdd || {}) },
      };
      if (shape) blk.shape = shape;
      if (_GL.乗せた && Math.abs(高底) > 1e-6) 乗せた棟.push({ blk, 高 });
      // 【円と判定できなかった印・2026-11-23 ユーザー指示「どれかわかるように赤い図形にしろ」】
      //   地図でタンク（円）として描かれているのに shapeFromOutline が円と見なせなかったもの。
      //   形が崩れているか、タイルの境目で切れている。赤くして目で探せるようにする。
      // 【いびつだった印】タンクは必ず円柱になるが、点列が円と見なせなかったものは赤くして
      //   「元の形が崩れている（測量の誤差・タイルの切れ）」と分かるようにする。
      // 範囲で切り取ったタンクは丸くないのが正しいので、いびつの印（赤）を付けない（2026-11-28）
      const _いびつ = !_切った && (it.種別 === "タンク") && !((typeof shapeFromOutline === "function") && shapeFromOutline(pts));
      // 【色は取り込み元（レイヤの表）が決める・2026-11-24】
      //   ここに `if (種別 === "道路")` を書かない。gsiTiles.js の GSI_IMPORT_LAYERS が it.color を渡す。
      const 色 = _いびつ ? "#EF4444" : (it.color || BLD_COLORS[(c - 1) % BLD_COLORS.length]);
      新.push({ id: "bld" + c, label: "取込" + c, color: 色, blocks: [blk] });
    }
    if (!新.length && !新面.length) return { 足した: 0, 重複, 重なり, 交差, 塗り: 0 };
    // 【地面があれば、乗せるか聞く・2026-11-27 ユーザー報告
    //   「地面を作った後、建物を作るにしたときに地面の上に置くか確認がなく地面を無視して配置される」】
    //   逆の順（建物 → 地面）では _liftBuildingsToGround が「乗せますか？」と聞くのに、
    //   この順（地面 → 建物）は黙って乗せていた＝**順番で振る舞いが違った**。同じく聞く。
    //   いいえなら従来どおり基準面 0 に置き、_src.GL は null（＝後で地面を作り直したとき、もう一度聞かれる）。
    //   聞くのは**高さが 0 から変わる建物があるときだけ**（地面が平らなら聞かない）。
    //   旗 window.__ASK_GROUND_ON_IMPORT = false で聞かない（従来＝黙って乗せる）。
    let 乗せた数 = 乗せた棟.length;
    if (乗せた数 && !(typeof window !== 'undefined' && window.__ASK_GROUND_ON_IMPORT === false)
        && typeof window !== 'undefined' && typeof window.confirm === 'function') {
      const ok = window.confirm('地面があります。取り込む建物 ' + 乗せた数 + ' 件を地面の上に乗せますか？\n'
        + '（いいえ＝高さ 0m の基準面に置きます。道路などの地面に塗る面は、どちらでも地面に沿います）');
      if (!ok) {
        for (const { blk, 高 } of 乗せた棟) {
          blk.zBottom = 0; blk.zTop = 高;
          blk._src = { ...blk._src, GL: null };
        }
        乗せた数 = 0;
      }
    }
    if (乗せた棟.length) console.log('[地面] 取り込む建物 ' + 乗せた棟.length + ' 件のうち '
      + 乗せた数 + ' 件を地面の上に乗せた');
    bldPushUndo();
    bldCounter.current = c;
    if (新.length) setBuildings(prev => [...prev, ...新]);
    if (新面.length) setGroundAreas(prev => [...prev, ...新面]);
    return { 足した: 新.length, 重複, 重なり, 交差, 塗り: 新面.length,
      地面に乗せた: 乗せた数, 地面に乗せなかった: 乗せた棟.length - 乗せた数 };
  };
  // 取り込んだ分を全部消す（付ける入口だけ作らない・SHAPE_MODEL_SPEC §3.7）
  const removeMapBuildings = () => {
    const 今 = buildingsRef.current || [];
    const 残 = 今.filter(b => !(b.blocks || []).some(_取込の印));
    const 消 = 今.length - 残.length;
    // 【塗る面も同じボタンで消す・2026-11-24】blocks の印で消す作りなので、
    //   道路を立体から外した分をここで消さないと**消えなくなる**（Codex監査の指摘）
    const 面 = (groundAreasRef.current || []).length;
    if (!消 && !面) return 0;
    bldPushUndo();
    if (消) setBuildings(残);
    if (面) setGroundAreas([]);
    return 消 + 面;
  };
  // 〔⌁ 掃引〕の確定。通り（経路）＋ 欄の値 → ブロック1つ・2026-10-04
  // 【形ごとの処理を書かない】ここがやるのは「欄の値を makeSweptBlock へ渡す」だけ。
  //   ケーブルラックか配管か梁か切妻屋根かは、**断面と経路の違いでしかない**。
  //   形が増えても、ここには1行も足さない
  // 【作図の入力は機械的に運ぶ・2026-10-05】作り手が返した `_` で始まるフィールドを
  //   1つずつ書き写していたら、足したものを必ず書き忘れる。
  //   実測: `_baseM` を書き忘れ、あとで寸法を打ち直したとき**下端が 3m → 0m に落ちた**。
  const _作図の入力 = (blk) => { const o = {};
    Object.keys(blk || {}).forEach(k => { if (k.charAt(0) === '_') o[k] = blk[k]; });
    return o; };
  // 〔⌁ 沿わせる〕: 断面を通りに沿わせてブロック1つ。
  //   断面は「図に描いた輪郭」でも「決まった形」でもよい（断面を作る が振り分ける）。
  //   【ブロックを返す】引き抜く・回す・らせんと同じ形にして、**作り直し**（数値を変えると
  //     その場で作り直る）に乗せる。2026-10-19 まで沿わせるだけ即建屋化していた。
  const 沿わせるブロック = (輪郭, 通り) => {
    if (!通り || 通り.length < 2) return null;
    if (typeof makeSweptBlock !== 'function') return null;
    // 【原点に寄せ直さない・2026-10-19 実測】makeSweptBlock が断面の重心と下端を
    //   自分で測って正規化するので、作業平面の座標のまま渡してよい
    //   （引き抜く・回すが 輪郭の置き方 で相対に直しているのは、軸の位置も一緒に決めるため）。
    const 断面 = 断面を作る(輪郭); if (!断面) return null;
    // 【描いた輪郭は必ず立てる・2026-10-19 advisor 監査】断面を横たえる（flat）と、
    //   断面の高さが経路方向のずれに化けて**厚みが0に潰れる**。決まった断面のときだけ選べる。
    const 向き = (断面.kind === 'raw') ? 'frame'
      : (実効の断面の向き('path') === 'upright' ? 'frame' : 'flat');
    // 【描いた面の向きを立体へ渡す・2026-10-25 advisor 監査】
    //   引き抜く（引き抜きブロック）・回す（回す側ら）は 作業平面の枠 → place で
    //   描いた面の3Dの向きを立体へ渡している。**沿わせるだけが渡していなかった**ので、
    //   断面の向きが solidModel の暗黙の規約（x＝進む向きの左／y＝上）で決まり、
    //   通りの向き次第で 90° 回ったり左右が鏡映したりしていた。
    //   ユーザー報告『平面をどう回転させてどう動かしたんだ？』の正体がこれ。
    //   描いた輪郭のときだけ渡す（決まった断面は『幅×高さ』の定義なので従来どおり）。
    const _枠 = (断面.kind === 'raw') ? 作業平面の枠(作業平面, sweepBaseM) : null;
    const blk = makeSweptBlock(通り, sweepBulgeM, 断面, sweepBaseM,
      { orient: 向き, frame0: _枠 ? { A: _枠.u, B: _枠.v, N: _枠.n } : null,
        // 【置き方は利用者が決める・2026-10-26】回す角と、通りに乗せる点
        roll: sweepRollDeg || 0, anchor: sweepAnchor || 'bottom' });
    if (!blk) return null;
    return Object.assign({ points: blk.points, zBottom: blk.zBottom, zTop: blk.zTop,
      sweep: blk.sweep },
      // 【動詞と揃える・2026-10-18】旧 '掃引'。押したボタンは〔⌁ 沿わせる〕
      //   なのに棟の名前が「掃引1」になっていた（回す→回転体 は揃っていた）
      _作図の入力(blk), { _label: 画面語.できた物.path || '沿わせ' });
  };
  // （通りから建屋にする入口は作り直しの effect 1つ・2026-10-24。
  //   旧 finishSweepRoute はダブルクリックから直に建てていたが、effect と二重に建った）

  // 〔⟳ 回す〕: 軸を1点クリックするだけ。断面を水平に360°回す＝ドーム・タンク・球。
  // 【形ごとのボタンを作らない】回転体は「経路の特別な場合」なので、掃引の入口の中に収める。
  //   利用者が決めるのは 断面 × 回すかどうか × 下端 の3つだけ
  // 【断面（Profile）を作るのはここ1か所】・2026-10-06
  //   輪郭を描いたときはその点列をそのまま使い、そうでなければ決まった形から作る。
  //   引き抜く・回す・らせん の3つが同じ関数を通るので、片方だけ任意輪郭が効かない、が起きない。
  const 断面を作る = (輪郭) => {
    if (輪郭 && 輪郭.length >= 3) return { kind: 'raw', pts: 輪郭 };
    if (sweepProfile === 'draw') return null;   // 輪郭を描く設定なのに輪郭が無い＝作らない
    return { kind: sweepProfile, wM: sweepWM, hM: sweepHM, tM: sweepTM };
  };

  // 【ブロックと建屋化を分ける・2026-10-12】作り直し（操作や数値を変えたとき）が
  //   同じ道を通るようにするため。引き抜きが先にこの形になっていたのに揃えた。
  const 回すブロック = (軸, 輪郭, 下端M, 置く) => {
    if (!軸 || typeof makeRevolveBlock !== 'function') return null;
    const 断面 = 断面を作る(輪郭); if (!断面) return null;
    // 置く＝正準（鉛直軸）で作った回転体を、実際の軸（3Dの点と向き）へ合わせる
    const blk = makeRevolveBlock(断面,
      (下端M != null ? 下端M : sweepBaseM),
      { at: { x: 軸.x, y: 軸.y }, sweepDeg: sweepRevDeg, place: 置く || null });
    if (!blk) return null;
    return Object.assign({ points: blk.points, zBottom: blk.zBottom, zTop: blk.zTop,
      sweep: blk.sweep }, _作図の入力(blk), { _label: '回転体' });
  };
  const finishRevolve = (軸, 輪郭, 下端M) => {
    const b = 回すブロック(軸, 輪郭, 下端M); if (!b) return null;
    const 残 = Object.assign({}, b); delete 残.points;
    return finishBldOutline(b.points, null, 残, { forceBuilding: true });
  };

  // 【次にすること・2026-10-06】選んだ後に何を押せばよいか分からない、が一番の詰まり所だった。
  //   **操作（動詞）ごとに1つ**。形の名前（ドリル・バネ…）はここにも出さない
  const SWEEP_NEXT = {
    twist:   '図の空いた所を1回クリック（①作業平面に**垂直**に引き抜きます。'
             + '上から描けば真上へ、正面に描けば奥行き方向へ）',
    revolve: '図の空いた所を1回クリック（そこが軸。断面を360°回します）',
    path:    '図をクリックして**通り**（道すじ）の点を置きます。'
             + '断面は**道に直角に立てて**運ばれます。'
             + '上から描いた面は、上から見た奥行きがそのまま高さになります'
             + '（立つ姿は青い面で出ます）。ダブルクリックで終わり',
    helix:   '図の空いた所を1回クリック（そこが軸。軸のまわりを回りながら上がります）',
  };
  // 〔⬆ 引き抜く〕: 軸を1点クリックするだけ。断面を真上へ引き抜く（＝押し出し）。
  //   **ひねり**と**先細り**を掛けられるので、細長い矩形＋ひねり1080°＋先細り0.1 でドリルの刃になる。
  //   【形ごとの機能にしない】『ドリルを作る』ではなく『引き抜く』という汎用の操作1つ。
  //     ねじれた柱・ねじ・角錐・テーパー柱も同じ操作の数値違いで出る（2026-10-06 ユーザー裁定）。
  //   【らせんとの違い】らせんは断面を軸から離して運ぶので紐（コイル）になる。
  //     引き抜きは軸が断面の中にあるので刃になる。
  //   【断面を立てない】yaw（水平に回す）が効くのは横たえたときだけ。立てると回らない
  // 【ブロックを作る所と建屋にする所を分ける・2026-10-06】
  //   下見（3次元図に半透明で出す形）と本物が**同じ道**を通るようにするため。
  //   下見用に別の描き方を用意すると、見えている形と作られる形が食い違う（過去の裁定）。
  const 引き抜きブロック = (軸, 輪郭, 下端M) => {
    // 【作り手は solidModel の makeTwistBlock・2026-11-20】ここは画面の状態を値にして渡すだけ。
    //   作り直し（寸法の打ち直し）も同じ関数を通る
    if (!軸 || typeof makeTwistBlock !== 'function') return null;
    const 断面 = 断面を作る(輪郭); if (!断面) return null;
    const 高さ = Math.abs(sweepRiseM) > 1e-6 ? sweepRiseM : 4;
    const zB = (下端M != null ? 下端M : (sweepBaseM || 0));
    // 【作業平面に垂直へ置く・2026-10-24 ユーザー裁定】
    //   正準では必ず真上(+z)へ引き抜く（makeLineSweep の契約は変えない）。
    //   それを枠の法線 n へ合わせるのが place。上から描けば真上のまま、
    //   正面に描けば奥行き方向、横に描けば横方向へ伸びる。
    //   u＝法線／m＝正準の -x が向く先（スケッチの -x）。m×u が +v になり、
    //   描いた向きがそのまま保たれる。
    const _枠 = 作業平面の枠(作業平面, 下端M);
    const _置く = (_枠 && _枠.n) ? (() => {
      const o3 = 面の点を3Dへ(軸, _枠);
      const m3 = 面の向きを3Dへ({ x: -1, y: 0 }, _枠);
      return { ox: o3.x, oy: o3.y, oz: o3.z,
               ux: _枠.n.x, uy: _枠.n.y, uz: _枠.n.z,
               mx: m3.x, my: m3.y, mz: m3.z };
    })() : null;
    // 置くときの下端は置き場所(o)が持つ・高さが負のときの始まり（sw.startM）は makeTwistBlock が持つ。
    //   記録する下端は**実際に使った値**（旧: 下端M を渡されても sweepBaseM を記録していた）
    const b = makeTwistBlock(断面, 軸, { riseM: 高さ, twistDeg: sweepTwistDeg, r1: sweepR1,
                                       baseM: zB, place: _置く });
    return b ? Object.assign(b, { _label: '引き抜き' }) : null;
  };
  const finishTwist = (軸, 輪郭, 下端M) => {
    const b = 引き抜きブロック(軸, 輪郭, 下端M); if (!b) return null;
    const 残 = Object.assign({}, b); delete 残.points;
    return finishBldOutline(b.points, null, 残, { forceBuilding: true });
  };

  // 〔🌀 らせん〕: 軸を1点クリックするだけ。回りながら上がる＝バネ・らせんの手すり
  const らせんブロック = (軸, 輪郭) => {
    const _tr = (段) => { if (typeof window !== 'undefined') window.__HELIX_LAST = 段; };
    _tr('入った');
    // 【作り手は solidModel の makeHelixBlock・2026-11-20】作り直しも同じ関数を通る
    if (!軸 || typeof makeHelixBlock !== 'function') { _tr('軸か関数が無い'); return null; }
    const 断面 = 断面を作る(輪郭); if (!断面) { _tr('断面が無い'); return null; }
    const 生 = (typeof profilePoints === 'function') ? profilePoints(断面) : null;
    if (!生 || 生.length < 3) { _tr('断面が作れない'); return null; }
    _tr('断面OK');
    // 断面の重心を軸から『断面の幅ぶん』外へ置く（軸の上に置くと回っても形にならない）。
    //   半径は記録に残す（_radius）。作り直しで断面の幅を変えても、コイルの径は保つ
    const mpp = (typeof METERS_PER_PX === 'number' && METERS_PER_PX > 0) ? METERS_PER_PX : 0.1;
    const 半径 = Math.max(1, (sweepWM || 0.5) / mpp * 1.5);   // 軸から外へ
    const b = makeHelixBlock(断面, 軸, { turnDeg: sweepTurnDeg, riseM: sweepRiseM, r1: sweepR1,
                                       baseM: sweepBaseM || 0, radius: 半径 });
    if (!b) { _tr('断面が作れない'); return null; }
    _tr('作った');
    return Object.assign(b, { _label: 'らせん' });
  };
  const finishHelix = (軸, 輪郭) => {
    const b = らせんブロック(軸, 輪郭); if (!b) return null;
    const 残 = Object.assign({}, b); delete 残.points;
    return finishBldOutline(b.points, null, 残, { forceBuilding: true });
  };


  // 【平面作図 → 引き抜く】描いた輪郭を断面にして、選んである操作に渡す（2026-10-06）。
  //   輪郭の重心をそのまま軸にするので、描いた場所にそのまま立ち上がる。
  //   点は図の絶対位置なので、重心を原点に寄せた相対座標で渡す（決まった形の断面と同じ扱い）。
  // 【作業平面の枠・1か所に・2026-10-16 advisor監査】
  //   作業平面の2D座標 (x,y) と3Dの対応を**ここだけ**で決める。
  //   o＝面の原点／u＝2Dのx方向／v＝2Dのy方向。すべて**グリッド空間**（z もグリッド）。
  //   【なぜ1つにするか】同じ写像が各所に手書きされ、横（Y-Z）だけ食い違っていた
  //     （面は x=TW/2 に置くのに、軸は y=TH/2 に置いていた）。
  // 【段0-b・2026-11-20 advisor監査】第1引数は作業平面の**記録**
  //   {kind:'base', axis:'plan'|'elev'|'side'} ／ {kind:'face', …}。文字列はこの先頭の1行で記録に直す
  //   （作業平面へ正対(v) など軸だけ分かれば足りる呼び口のため）。以降は記録だけを見る。
  //   知らない入力（null・未知の kind）は **null を返す**（上からに落とさない＝fail-closed）。
  //   面の位置：上からの高さは sweepBaseM（「下端」欄）。正面は y=TH/2、横は x=TW/2（中央）。
  //   【段0-c・2026-11-20 ユーザー裁定】正面・横の位置を数値で打つ欄（offsetM）は撤去した。
  //     位置を変えたいときは、作った箱の面を〔⬚ 面を選ぶ〕で選ぶ（記録 {kind:'face'}）。
  //   face の記録は面の名前と、選んだ時点の枠（スナップショット）を持つ。ここはスナップショットを返すだけ
  //   （面→枠の作り方は solidModel の planeFrameFromFace／planeFrameFromPointNormal 1か所）。
  //   pick（面を選んでいる最中）は平面ではないので null。
  const 作業平面の枠 = (面, 下端M) => {
    const rec = (typeof 面 === 'string') ? { kind: 'base', axis: 面 } : 面;
    if (!rec) return null;
    if (rec.kind === 'face') return rec.枠 || null;
    if (rec.kind !== 'base') return null;
    const mpp = (typeof METERS_PER_PX === 'number' && METERS_PER_PX > 0) ? METERS_PER_PX : 0.1;
    const z0 = ((下端M != null ? 下端M : (sweepBaseM || 0)) / mpp);
    // 【法線は枠が持つ・2026-10-24】n = u × v。引き抜く向き（面に垂直）がこれ。
    //   呼ぶ側で毎回外積を書くと、面を1つ足したとき片方だけ古くなる。
    if (rec.axis === 'elev') return { o: { x: 0, y: TH / 2, z: 0 },
      u: { x: 1, y: 0, z: 0 }, v: { x: 0, y: 0, z: 1 }, n: { x: 0, y: -1, z: 0 } };
    if (rec.axis === 'side') return { o: { x: TW / 2, y: 0, z: 0 },
      u: { x: 0, y: 1, z: 0 }, v: { x: 0, y: 0, z: 1 }, n: { x: 1, y: 0, z: 0 } };
    if (rec.axis === 'plan') return { o: { x: 0, y: 0, z: z0 }, u: { x: 1, y: 0, z: 0 },
      v: { x: 0, y: 1, z: 0 }, n: { x: 0, y: 0, z: 1 } };
    return null;
  };
  const 面の点を3Dへ = (p, 枠) => ({
    x: 枠.o.x + 枠.u.x * p.x + 枠.v.x * p.y,
    y: 枠.o.y + 枠.u.y * p.x + 枠.v.y * p.y,
    z: 枠.o.z + 枠.u.z * p.x + 枠.v.z * p.y });
  const 面の向きを3Dへ = (d, 枠) => ({
    x: 枠.u.x * d.x + 枠.v.x * d.y,
    y: 枠.u.y * d.x + 枠.v.y * d.y,
    z: 枠.u.z * d.x + 枠.v.z * d.y });
  // 【作業平面の写像は枠から読む・段0-a・2026-11-20 advisor監査】
  //   枠ができた後も、面の向きと位置を 'plan'/'elev'/'side' の名前で手書きする所が
  //   5か所残っていた（スケッチ面の表示・掴む向き・面内の2軸・3次元図へ写す・矢印）。
  //   しかも正面の法線が食い違っていた：枠は n=(0,-1,0)（立体もこの向きに伸びる）なのに
  //   矢印と掴む向きは +y。実測：正面に描いた面は y=2016、立体は y=1986〜2016 なのに
  //   矢印は +y を指していた（引っ張る向きと伸びる向きが逆）。
  //   単位は枠の中だけ「全部グリッド（z もグリッド）」。出口で換算する：
  //     立体の頂点 … z をメートルへ（×mpp）／3次元図の画面 … _bldZPx(メートル)
  //   【陽性対照】window.__PLANE_FRAME_ONE = false で従来（名前で手書き）。
  const _枠から読むか = () => !(typeof window !== 'undefined' && window.__PLANE_FRAME_ONE === false);
  const _mpp作業 = () => ((typeof METERS_PER_PX === 'number' && METERS_PER_PX > 0) ? METERS_PER_PX : 0.1);
  //   作業平面の2D点 → 立体の頂点の約束（x,y＝グリッド／z＝メートル）
  const 面の点を立体へ = (p, 枠) => { const q = 面の点を3Dへ(p, 枠);
    return { x: q.x, y: q.y, z: q.z * _mpp作業() }; };
  //   引き抜く向き（面に垂直）。矢印の表示と面を掴んだときの換算が同じ値を読む
  //   枠が無い（作業平面が決まっていない）ときは null（呼ぶ側は何もしない）
  const 引き抜く向き = () => {
    if (!_枠から読むか()) return (bldDrawView === 'elev') ? { nx: 0, ny: 1, nz: 0 }
      : (bldDrawView === 'side') ? { nx: 1, ny: 0, nz: 0 } : { nx: 0, ny: 0, nz: 1 };
    const f = 作業平面の枠(作業平面, sweepBaseM); if (!f) return null;
    return { nx: f.n.x, ny: f.n.y, nz: f.n.z };
  };
  //   面の中の2軸（掴むとき「正面から見ていて潰れているか」の基準）
  const 面内の2軸 = () => {
    if (!_枠から読むか()) return (bldDrawView === 'elev') ? [[1, 0, 0], [0, 0, 1]]
      : (bldDrawView === 'side') ? [[0, 1, 0], [0, 0, 1]] : [[1, 0, 0], [0, 1, 0]];
    const f = 作業平面の枠(作業平面, sweepBaseM); if (!f) return null;
    return [[f.u.x, f.u.y, f.u.z], [f.v.x, f.v.y, f.v.z]];
  };
  //   旧の道（旗を切ったとき）は軸の名前で分けるので、記録から名前を取り出す口
  const _軸名 = (v) => (typeof v === 'string') ? v
    : (v && v.kind === 'base' ? v.axis : null);
  // 【軸の2点から面の中の座標系を出す】またぐ判定・断面・置き方が同じ式を使う
  const 回す軸の枠 = () => {
    const A = revolveAxis && revolveAxis.a, B = revolveAxis && revolveAxis.b;
    if (!A || !B) return null;
    const dx = B.x - A.x, dy = B.y - A.y, L = Math.hypot(dx, dy);
    if (!(L > 1e-6)) return null;
    // 【回る向きはここだけで決める・2026-10-18 ユーザー要望】
    //   「回すときの回転が半時計か時計回りかが逆の方もえらべるようにしろ」
    //   回る向きは**軸の向き u の右ねじ**なので、u を反転すれば逆回りになる。
    //   角度(sweepDeg)を負にする手は使わない：接線が反転して断面が径方向に裏返り、
    //   内径が膨らむ（solidModel.js の clipSectionLeft のコメントにある実測と同じ症状）。
    //   またぐ判定・沿い・置く位置・ドラッグの円は全部この枠から u を読むので、
    //   ここ1か所で反転すれば全部がそろって追従する。
    const sg = (revolveDir < 0) ? -1 : 1;
    return { A: A, u: { x: sg * dx / L, y: sg * dy / L },
                    n: { x: -sg * dy / L, y: sg * dx / L } };
  };
  //   軸からの符号つき距離（正負が混ざる＝軸をまたいでいる）
  const 軸からの距離 = (p, 枠2) => (p.x - 枠2.A.x) * 枠2.n.x + (p.y - 枠2.A.y) * 枠2.n.y;
  // 【どちらの側か → 3Dの向き・述語は1つ・2026-10-18 ユーザー報告】
  //   「回すの0度の位置は作った面だろ。180度の位置になってるぞ」
  //   立体を置く向き（place の m）と、画面の円弧の0°（回す円の枠の e1）が
  //   **同じ値**を読まないと、つまみは32°なのに立体は反対側から始まる。
  //   符号は呼ぶ側が渡す（+1＝軸の法線の正側／-1＝負側）。
  //   【なぜ呼ぶ側が渡すか・2026-10-18】軸が輪郭の中を通るときは**両側に断面がある**ので、
  //     『断面のある側』を自分で決めると必ず片方を取りこぼす（advisor 監査）。
  const 側の向き = (符号, 枠2, 枠) => {
    if (!枠2 || !枠) return null;
    const s = (符号 < 0) ? -1 : 1;
    const v = 面の向きを3Dへ({ x: 枠2.n.x * s, y: 枠2.n.y * s }, 枠);
    if (!v) return null;
    const L = Math.hypot(v.x, v.y, v.z); if (!(L > 1e-9)) return null;
    return { x: v.x / L, y: v.y / L, z: v.z / L };
  };
  // 主たる側（＝画面のつまみの 0° をどちらに描くか）。
  //   軸からの距離の合計が大きい側。**頂点の平均（重心）では対称な断面で軸上に落ちて
  //   半径0になり、つまみが出なくなる**（advisor 指摘）。同じだけなら正側に寄せる。
  const 主たる側の符号 = (pts, 枠2) => {
    if (!pts || !pts.length || !枠2) return 1;
    let 正 = 0, 負 = 0;
    for (const p of pts) { const d = 軸からの距離(p, 枠2);
      if (d > 0) 正 += d; else 負 -= d; }
    return (負 > 正) ? -1 : 1;
  };
  const 断面のある向き = (pts, 枠2, 枠) => 側の向き(主たる側の符号(pts, 枠2), 枠2, 枠);
  // 【回すの置き方は「側」ごと・2026-10-18 ユーザー裁定／advisor 監査】
  //   「軸が面上にあるときに図形が生成されない。軸に則って回転させてそれで出来る体積を
  //     作ればよいのに」
  //   軸が輪郭の中を通るときは、軸で2つに割って**それぞれを自分の位置から回す**。
  //   返すのは置き方の配列（またがないときは1つ、またぐときは2つ）。
  //
  //   【なぜ片側に畳まないか】絶対値で片側へ写すと、対称な断面（四角の真ん中に軸＝
  //     円筒を作るいちばん普通の操作）で畳んだ点が2点になり、**いまと同じく何も出ない**。
  //     頂点だけ絶対値を取っても軸上で折り返さないので、軸に触れない殻になる。
  //     部分回転では右側は 0°→θ、左側は 180°→180°+θ を掃くので、寄せると嘘になる。
  //
  //   【どうやって側を取り分けるか】makeRevolveBlock は中で左半分(x<=0)に切る。
  //     だから呼ぶ側は『鏡映するかどうか』を変えるだけでよい：
  //       符号 +1（正側を作る）… x = -距 にして写す → 正側が左半分に来て残る
  //       符号 -1（負側を作る）… x =  距 のまま      → 負側が左半分なので残る
  //     新しい切り方は書かない。
  const 回す側ら = (pts) => {
    if (!pts || pts.length < 3) return [];
    const 枠2 = 回す軸の枠(); if (!枠2) return [];        // 軸が2点そろうまで作らない
    const 距 = pts.map(p => 軸からの距離(p, 枠2));
    const 沿 = pts.map(p => (p.x - 枠2.A.x) * 枠2.u.x + (p.y - 枠2.A.y) * 枠2.u.y);
    const s0 = Math.min.apply(null, 沿);
    const 枠 = 作業平面の枠(作業平面, sweepBaseM); if (!枠) return [];
    const A3 = 面の点を3Dへ(枠2.A, 枠), u3 = 面の向きを3Dへ(枠2.u, 枠);
    // 断面の下端（軸方向のいちばん手前）が置き場所の原点になる
    const O3 = { x: A3.x + u3.x * s0, y: A3.y + u3.y * s0, z: A3.z + u3.z * s0 };
    const 作る = (符号) => {
      // 【軸まわりの位相】正準では断面を必ず左半分に切るので、『正準の -x が実空間で
      //   どこを向くか』を渡さないと 0° が成り行きになる（2026-10-18 の不具合）
      const m3 = 側の向き(符号, 枠2, 枠);
      return { 軸: { x: A3.x, y: A3.y },
               相対: pts.map((p, i) => ({ x: (符号 > 0 ? -距[i] : 距[i]), y: 沿[i] - s0 })),
               下端: 0,
               置く: Object.assign({ ox: O3.x, oy: O3.y, oz: O3.z,
                                     ux: u3.x, uy: u3.y, uz: u3.z },
                 m3 ? { mx: m3.x, my: m3.y, mz: m3.z } : null) };
    };
    // どちらの側に中身があるか。閾は 軸をまたぐか() と同じ 0.05（判定を書き分けない）
    const 正 = 距.some(d => d > 0.05), 負 = 距.some(d => d < -0.05);
    // 【またぐときは「ガワ」1つにまとめる・2026-10-19 ユーザー裁定】
    //   「重なりはガワだけができればいいんじゃないの？内部構造として存在する必要はない。」
    //   左右を別々の立体にすると、180°を超えて回したとき**同じ体積を2回描く**
    //   （重なって色が濃くなる）。各高さで軸からいちばん遠い所を拾って1つの断面にすれば、
    //   内部に面が生まれないので重なりも消える（走査線で拾う。頂点だけ絶対値を取ると
    //   対称な断面で2点に潰れて何も作れない）。
    if (正 && 負 && typeof sectionEnvelopeLeft === 'function') {
      const 相対 = pts.map((p, i) => ({ x: 距[i], y: 沿[i] - s0 }));
      const ガワ = sectionEnvelopeLeft(相対);
      if (ガワ && ガワ.length >= 3) {
        // 0°をどちらに置くか。両側にあるので『主たる側』（軸からの距離の合計が大きい方）
        const m3 = 側の向き(主たる側の符号(pts, 枠2), 枠2, 枠);
        return [{ 軸: { x: A3.x, y: A3.y }, 相対: ガワ, 下端: 0,
                  置く: Object.assign({ ox: O3.x, oy: O3.y, oz: O3.z,
                                        ux: u3.x, uy: u3.y, uz: u3.z },
                    m3 ? { mx: m3.x, my: m3.y, mz: m3.z } : null) }];
      }
    }
    const 出 = [];
    if (正) 出.push(作る(1));
    if (負) 出.push(作る(-1));
    // どちらにも届かない（軸の上に潰れている）ときは作らない
    return 出;
  };
  // 【輪郭の置き方を1か所に・2026-10-06】軸をどこに取るか・下端をどうするかは、
  //   下見と確定で**同じ計算**でなければならない（違うと見えている形と作られる形がずれる）
  const 輪郭の置き方 = (pts) => {
    if (!pts || pts.length < 3) return null;
    const mpp = (typeof METERS_PER_PX === 'number' && METERS_PER_PX > 0) ? METERS_PER_PX : 0.1;
    let cx = 0, cy = 0; pts.forEach(p => { cx += p.x; cy += p.y; });
    cx /= pts.length; cy /= pts.length;
    // （回すの置き方は 回す側ら() にある・2026-10-18。またぐときは両側ぶん返る）
    // 【面で分岐しない・2026-10-24 ユーザー裁定】
    //   旧：立面で描いた輪郭を『平面の足跡』に読み替えて真上へ引き抜いていた。
    //   ＝どの面に描いたかをここで捨てていたので、正面に描いても真上にしか伸びなかった。
    //   いまは重心を原点にした相対だけを返し、**どっちへ伸ばすかは枠の法線**が決める
    //   （正準で真上に作って place で置く。2026-10-16 の回すと同じ段取り）。
    return { 軸: { x: cx, y: cy },
             相対: pts.map(p => ({ x: p.x - cx, y: p.y - cy })), 下端: null };
  };

  // 【描いた輪郭 → ブロック列】建屋にはしない。作ると**作り直し**が同じ道を通る（2026-10-12）
  //   【なぜ配列か・2026-10-18】回すで軸が輪郭の中を通るときは、軸で割った**2つ**になる。
  //     1個のときと2個のときで道を分けない（分けると必ず片方が古くなる）。
  const 輪郭のブロックら = (pts) => {
    if (sweepMode === 'revolve') {
      return 回す側ら(pts).map(置 => 回すブロック(置.軸, 置.相対, 置.下端, 置.置く))
        .filter(Boolean);
    }
    if (sweepMode === 'path') {
      // 【断面の決まり方は2通り・2026-10-24 ユーザー裁定】
      //   面を作ってあれば その面が断面（2026-10-19 からの流れ・残す）／
      //   面が無ければ ②輪郭のプルダウン（矩形・円・H形鋼…）。
      //   どちらでも通りは sweepWay で、点を置くたびにここを通って作り直される。
      const 輪 = 面がそろったか() ? pts : null;
      const b = 沿わせるブロック(輪, sweepWay);
      return b ? [b] : [];
    }
    const 置 = 輪郭の置き方(pts); if (!置) return [];
    const b = (sweepMode === 'helix') ? らせんブロック(置.軸, 置.相対)
                                      : 引き抜きブロック(置.軸, 置.相対, 置.下端);
    return b ? [b] : [];
  };
  const finishDrawnProfile = (pts) => {
    const bs = 輪郭のブロックら(pts); if (!bs.length) return null;
    return finishBldOutlineBlocks(bs);
  };

  // 建物データのjson保存/読込（spec 7.6: 今後の新規データはjson）
  const exportBuildingsJson = useCallback(() => {
    // 【2026-09-27】CSGボディも一緒に保存する（別ファイルにすると対応が取れなくなる）
    const text = bcExportBuildings(buildingsRef.current || [], bodiesRef.current || []);
    const blob = new Blob([text], { type: 'application/json' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'wanol_buildings.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  }, []);
  const importBuildingsJson = useCallback((text) => {
    const r = bcImportBuildings(text);
    if (!r.ok) return r.error;
    bldPushUndo(); // 読込前の状態をundoに積む（誤読込から戻せるように）
    setBuildings(r.buildings);
    setSolids(buildingsToSolids(r.buildings));
    // 【2026-09-27】CSGボディ。v1 のデータなら空配列が来る（今あるものを消す＝読み込んだ図と一致させる）
    setBodies(r.bodies || []);
    // 採番が既存idと衝突しないよう進める（建屋と同じ作法）
    let maxB = 0;
    (r.bodies || []).forEach(b => { const m = /^body(\d+)$/.exec(b.id); if (m) maxB = Math.max(maxB, +m[1]); });
    if (bodyCounter.current < maxB) bodyCounter.current = maxB;
    // 立体に貼った機器の採番も進める（進めないと読込後に同じ id を作ってしまう）
    let maxBI = 0;
    (r.bodies || []).forEach(b => (b.icons || []).forEach(ic => {
      const m = /^bic(\d+)$/.exec(String(ic.id || '')); if (m) maxBI = Math.max(maxBI, +m[1]); }));
    if (bodyIconCounter.current < maxBI) bodyIconCounter.current = maxBI;
    // bldカウンタを既存idと衝突しないよう進める
    let maxN = 0;
    r.buildings.forEach(b => { const m = /^bld(\d+)$/.exec(b.id); if (m) maxN = Math.max(maxN, +m[1]); });
    if (bldCounter.current < maxN) bldCounter.current = maxN;
    return null;
  }, [bldPushUndo]);

  // ===== 仕切り・扉（建物内部 Phase B・buildingCore.js）=====
  // 部屋認識は保存データに持たず、buildings から bcDeriveRooms で毎回導出する（描画側）
  const _patchFloor = useCallback((buildingId, floorId, fn) => {
    setBuildings(prev => prev.map(b => b.id !== buildingId ? b : {
      ...b,
      floors: (b.floors || []).map(f => f.id === floorId ? fn(f) : f),
    }));
  }, []);
  const onAddPartition = useCallback((buildingId, floorId, a, b, kind) => {
    const bld = (buildingsRef.current || []).find(x => x.id === buildingId);
    const floor = bld && (bld.floors || []).find(f => f.id === floorId);
    if (!floor) return '階が見つかりません';
    const part = bcNewPartition(a, b, kind);
    const v = bcValidatePartition(bld, floor, part);
    if (!v.ok) return v.errors.join(' / ');
    _patchFloor(buildingId, floorId, f => ({ ...f, partitions: [...(f.partitions || []), part] }));
    return null;
  }, [_patchFloor]);
  const onUpdatePartition = useCallback((buildingId, floorId, partId, patch) => {
    _patchFloor(buildingId, floorId, f => ({
      ...f,
      partitions: (f.partitions || []).map(p => p.id === partId ? { ...p, ...patch } : p),
      // 壁→透明仕切りへ変えたら、その仕切りの扉は削除（透明仕切りに扉は乗らない: spec 7.2）
      doors: patch.kind === 'clear' ? (f.doors || []).filter(d => d.partitionId !== partId) : (f.doors || []),
    }));
  }, [_patchFloor]);
  // 【統一編集モデル・spec 段階1】床も壁も同格の「仕切り」として編集する唯一の出口。
  // 検証(外形内・扉の収まり)は bcApplyPartEdit の中で行われ、失敗時は building を変えない。
  // 個別の onUpdateFloor / onUpdatePartition は既存経路として残すが、
  // 要素一覧からの編集はすべてここを通す（出口を1本に絞るのが設計の要）
  const onApplyPartEdit = useCallback((buildingId, editPartId, patch) => {
    const b = (buildingsRef.current || []).find(x => x.id === buildingId);
    if (!b) return '構造体が見つかりません';
    const res = bcApplyPartEdit(b, editPartId, patch);
    if (!res.ok) return res.errors.join(' / ');
    setBuildings(prev => prev.map(x => x.id === buildingId ? res.building : x));
    return null;
  }, []);
  const onDeletePartition = useCallback((buildingId, floorId, partId) => {
    // 仕切り削除時はその仕切りの扉も道連れ削除（孤児防止。配電盤deleteDoorと同じ思想）。
    // 機器の道連れは「壁の機器」だけでなく「その壁の扉に付いた機器」まで2段になるので、
    // 条件をここに書かず bcPruneOrphanIcons に任せる（書くと必ず片方を忘れる）
    _patchFloor(buildingId, floorId, f => bcPruneOrphanIcons({
      ...f,
      partitions: (f.partitions || []).filter(p => p.id !== partId),
      doors: (f.doors || []).filter(d => d.partitionId !== partId),
    }));
  }, [_patchFloor]);
  // uM を渡せば「その位置」に置く（配置モードで壁をクリックしたとき）。
  // 省略時は従来どおり壁の中央。位置を指定する手段が無いのが元の作りの問題だった
  const onAddDoor = useCallback((buildingId, floorId, partId, uM) => {
    const bld = (buildingsRef.current || []).find(x => x.id === buildingId);
    const floor = bld && (bld.floors || []).find(f => f.id === floorId);
    const part = floor && (floor.partitions || []).find(p => p.id === partId);
    if (!part) return '仕切りが見つかりません';
    if (part.kind !== 'wall') return '扉は壁にのみ設置できます（透明仕切りは常時開放です）';
    const lenM = bcPartitionLenM(part);
    const door = bcNewDoor(partId, uM != null ? uM : lenM / 2);
    if (door.widthM > lenM) return '壁が短すぎて扉が入りません';
    // 壁の端からはみ出さない位置へ収める（クランプの式は bcApplyDoorEdit と同じ意味）
    const half = door.widthM / 2;
    door.uM = Math.max(half, Math.min(Math.max(half, lenM - half), door.uM));
    _patchFloor(buildingId, floorId, f => ({ ...f, doors: [...(f.doors || []), door] }));
    return null;
  }, [_patchFloor]);
  // 扉の編集はすべてここを通す（壁の onApplyPartEdit と同じ形）。
  // 検証は bcApplyDoorEdit の中だけで行い、呼び出し側に散らさない
  const onApplyDoorEdit = useCallback((buildingId, floorId, doorId, patch) => {
    const b = (buildingsRef.current || []).find(x => x.id === buildingId);
    if (!b) return '構造体が見つかりません';
    const res = bcApplyDoorEdit(b, floorId, doorId, patch);
    if (!res.ok) return res.errors.join(' / ');
    setBuildings(prev => prev.map(x => x.id === buildingId ? res.building : x));
    return null;
  }, []);
  const onDeleteDoor = useCallback((buildingId, floorId, doorId) => {
    // 扉に付いた機器も道連れ（孤児を作らない）。条件は bcPruneOrphanIcons の1本だけ
    _patchFloor(buildingId, floorId, f => bcPruneOrphanIcons({
      ...f, doors: (f.doors || []).filter(d => d.id !== doorId) }));
  }, [_patchFloor]);

  // ── 機器アイコン（Phase C）。扉とまったく同じ形にそろえる ──
  // side は「壁線へ射影する前のカーソル位置」がどちら側かで決める（監査指摘）
  // 【取付先は opts.doorId の有無だけで決まる】壁に直接貼るか、扉の面に貼るか。
  // 収める式は bcClampIcon の1本に統一する（もとはここに同じ式が二重実装されていた）
  const onAddIcon = useCallback((buildingId, floorId, partId, sM, side, opts) => {
    const bld = (buildingsRef.current || []).find(x => x.id === buildingId);
    const floor = bld && (bld.floors || []).find(f => f.id === floorId);
    if (!floor) return '階が見つかりません';
    const o = opts || {};
    // tM（面の下端から機器の中心までの高さ）は、3Dで面をクリックできたときだけ渡ってくる。
    // 渡ってこなければ既定の高さに置く（2Dからの配置・従来どおり）
    const _tM = Number.isFinite(o.tM) ? o.tM : null;
    const ic = o.doorId ? bcNewDoorIcon(o.doorId, side, sM, _tM, o)
                        : bcNewIcon(partId, side, sM, _tM, o);
    const fm = bcIconFrame(floor, ic, bld);
    if (!fm) return o.doorId ? '扉が見つかりません' : '仕切りが見つかりません';
    if (ic.wM > fm.spanSM) return o.doorId ? '扉が小さすぎて機器が入りません'
                                           : '壁が短すぎて機器が入りません';
    Object.assign(ic, bcClampIconOnFrame(fm, ic));
    _patchFloor(buildingId, floorId, f => ({ ...f, icons: [...(f.icons || []), ic] }));
    return null;
  }, [_patchFloor]);
  // ══ 建屋の外周壁（曲面を含む）に機器を置く ・2026-10-01 ══
  // 【なぜ要るか】これまで機器は「内部の仕切り」と「扉」にしか貼れず、建屋のガワに貼れなかった。
  //   イオンモールの扇形の外周にコンセント、が入口で弾かれていた。
  // 【どの壁に付くかはここで決めない】図面の点から bcPickOuterSpot が最寄りの外壁と
  //   その面の上の位置を返す。平面図・3次元図・建屋エディタが同じ述語を使う
  const onAddOuterIcon = useCallback((buildingId, floorId, gridPt, opts) => {
    const bld = (buildingsRef.current || []).find(x => x.id === buildingId);
    const floor = bld && (bld.floors || []).find(f => f.id === floorId);
    if (!floor) return '階が見つかりません';
    if (typeof bcPickOuterSpot !== 'function') return '未対応です';
    const o = opts || {};
    const spot = bcPickOuterSpot(bld, floor, gridPt, o.maxDistGrid, o.zM);
    if (!spot) return '外壁が見つかりません';
    const ic = bcNewOuterIcon(spot.outerKey, spot.side, spot.sM,
                              Number.isFinite(spot.tM) ? spot.tM : null, o);
    if (ic.wM > spot.frame.spanSM) return '外壁が短すぎて機器が入りません';
    Object.assign(ic, bcClampIconOnFrame(spot.frame, ic));
    _patchFloor(buildingId, floorId, f => ({ ...f, icons: [...(f.icons || []), ic] }));
    return null;
  }, [_patchFloor]);
  // 天井に機器を置く（照明など）。床置きと同じ icons[] に入れ、違いは貼った面だけ
  const onAddCeilIcon = useCallback((buildingId, floorId, gx, gy, opts) => {
    const bld = (buildingsRef.current || []).find(x => x.id === buildingId);
    const floor = bld && (bld.floors || []).find(f => f.id === floorId);
    if (!floor) return '階が見つかりません';
    if (typeof bcNewCeilIcon !== 'function') return '未対応です';
    const ic = bcNewCeilIcon(gx, gy, opts);
    Object.assign(ic, bcClampFloorIcon(floor, ic));
    _patchFloor(buildingId, floorId, f => ({ ...f, icons: [...(f.icons || []), ic] }));
    return null;
  }, [_patchFloor]);
  // 床置きの機器（仕様書8章 未決#3の解決）。壁面と同じ icons[] に入れる
  const onAddFloorIcon = useCallback((buildingId, floorId, gx, gy, opts) => {
    const bld = (buildingsRef.current || []).find(x => x.id === buildingId);
    const floor = bld && (bld.floors || []).find(f => f.id === floorId);
    if (!floor) return '階が見つかりません';
    const ic = bcNewFloorIcon(gx, gy, opts);
    Object.assign(ic, bcClampFloorIcon(floor, ic));
    _patchFloor(buildingId, floorId, f => ({ ...f, icons: [...(f.icons || []), ic] }));
    return null;
  }, [_patchFloor]);
  const onApplyIconEdit = useCallback((buildingId, floorId, iconId, patch) => {
    const b = (buildingsRef.current || []).find(x => x.id === buildingId);
    if (!b) return '構造体が見つかりません';
    const res = bcApplyIconEdit(b, floorId, iconId, patch);
    if (!res.ok) return res.errors.join(' / ');
    setBuildings(prev => prev.map(x => x.id === buildingId ? res.building : x));
    return null;
  }, []);
  const onDeleteIcon = useCallback((buildingId, floorId, iconId) => {
    _patchFloor(buildingId, floorId, f => ({ ...f, icons: (f.icons || []).filter(x => x.id !== iconId) }));
  }, [_patchFloor]);

  // winState は下方で宣言するため、ここから直接参照するとTDZ（初期化前アクセス）になる。ref経由で読む
  const winStateRef = useRef(null);

  // Ctrl+Z / Ctrl+Y: 建物undo/redo（親で一元管理、CesiumMap2インスタンスからの2重発火を防止）
  useEffect(() => {
    const onKey = (e) => {
      if (!(e.ctrlKey || e.metaKey)) return;
      // 入力欄で文字を打っている最中の Ctrl+Z を横取りしない
      if (!bcCanHandleDeleteKey()) return;
      // 配電盤エディタは自前の undo を持つ。最前面がそれなら建物undoは譲る（spec 12.4）
      if (fwOwnsKeyboard('panelEditor', winStateRef.current)) return;
      if (e.key === 'z' && !e.shiftKey) { e.preventDefault(); bldUndo(); }
      if (e.key === 'y' || (e.key === 'z' && e.shiftKey)) { e.preventDefault(); bldRedo(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [bldUndo, bldRedo]);

  // 建屋エディタ状態
  const [cab3dArrow, setCab3dArrow] = useState(null); // 3次元図 法線矢印: {cx,cy,cz,nx,ny,nz,color,buildingId,faceId}
  const [ppDrag, setPPDrag] = useState(null); // pushpullドラッグ: {faceId,solidId,nx,ny,nz,cx,cy,cz,startClientX,startClientY,startSolid,svgPerUnit}
  // CSG立体の押し引きのプレビュー（ドラッグ中は manifold を回さず、押し出す箱だけ薄く重ねる）
  const [csgPush, setCsgPush] = useState(null); // { bodyId, groupIdx, depthM }
  // 面の上に描いた下書き。**選んでいる面に従属**させる（面が変われば無効・Codex監査）
  //   { bodyId, groupIdx, mode:'rect'|'poly', pts:[[a,b],...], previewPt, done }
  //   確定した形は矩形も多角形も**頂点の列 pts** に統一する（器を2つ持たない・Codex監査）
  const [csgSketch, setCsgSketch] = useState(null);
  // 面の上に何を描くか。誤操作を減らすため**明示の切り替え**にする（自動判定にしない・Codex監査）
  const [csgFaceDrawMode, setCsgFaceDrawMode] = useState('rect'); // 'rect' | 'poly'
  // 【寸法を打って押し出す・2026-09-30】手本のCAD（ハシビロCAD）の「寸法を入力して押し出せます」。
  //   **利用者が打った文字**だけを持つ。ドラッグ中の量はここへ書き戻さない
  //   （1つの入れ物に「操作中の値」と「利用者の値」の2つの意味を持たせない・Codex監査）
  const [csgPushText, setCsgPushText] = useState('1');
  const csgSketchRef = useRef(null);
  csgSketchRef.current = csgSketch;
  const ppDragRef = useRef(null); // ppDragのref版（stale closure回避）
  const cab3dAnimCancelRef = useRef(null); // 3次元図ダブルクリックアニメーション中断用
  const focusAnimCancelRef = useRef(null); // カメラアイコンフォーカスアニメーション中断用
  // focusGridPos は下方で定義されるため、上方のメッセージ受信から呼べるようrefで橋渡しする
  const focusGridPosRef = useRef(null);
  const secFocusAnimCancelRef = useRef(null); // 矢視図フォーカスアニメーション中断用
  const [cabSecMode, setCabSecMode] = useState(false); // 3次元図での矢視図追加モード
  const cabSecModeRef = useRef(false); cabSecModeRef.current = cabSecMode;
  const [bldEditMode, setBldEditMode] = useState(false);
  const [hovBldId, setHovBldId] = useState(null); // hover building ID (non-edit mode)
  const [hovBldView, setHovBldView] = useState(null); // hover building のビューID（'plan'|'elev'|'side'|sec.id）
  const [hovNodeView, setHovNodeView] = useState(null); // hover node のビューID（'plan'|'elev'|'side'|'cab'|sec.id）
  const [selectedBldView, setSelectedBldView] = useState(null); // 建屋選択したビューID（'plan'|'elev'|'side'|sec.id）
  const [bldDraw, setBldDraw] = useState(null); // { startX, startY, curX, curY } (pixel coords for rect mode)
  const [selectedBld, setSelectedBld] = useState(null); // building id
  // 【既定は「輪郭を描く」・2026-10-14 ユーザー裁定】
  //   「そもそも掃引がその段階でいらないんじゃないの？まず平面を作ることに集中し…」
  //   旧: 'rect'（矩形ドラッグ）＝輪郭を描くには先に〔掃引〕を押す必要があった。
  //   ほかの形（矩形・円・扇形…）は近道として残す。
  const [bldDrawMode, setBldDrawMode] = useState('sweep'); // 'sweep'（輪郭を描く）| 'rect' | 'poly' | 'circle' | 'sector' …
  // 扇形（イオンモールのような扇形の空間）。中心から外へドラッグして向きと外半径を決め、
  // 開き角と内側のくり抜きはここで指定する
  const [sectorSweepDeg, setSectorSweepDeg] = useState(90);
  const [sectorInnerPct, setSectorInnerPct] = useState(50);
  // 【2026-10-03】螺旋階段（扇形の段板をらせんに並べる）と、らせんの帯（経路に沿わせる）。
  //   どちらも「形が平面図形×一定の高さ」から出られないという欠陥への答え
  const [stairSteps, setStairSteps] = useState(16);        // 段数
  const [stairTotalDeg, setStairTotalDeg] = useState(360); // 全体で回る角度
  const [stairRiseM, setStairRiseM] = useState(3.2);       // 全体で上がる高さ[m]
  const [stairInnerPct, setStairInnerPct] = useState(20);  // 中心の穴（外半径に対する%）
  const [helixTurnDeg, setHelixTurnDeg] = useState(720);   // らせんが回る角度
  const [helixRiseM, setHelixRiseM] = useState(6);         // らせんが上がる高さ[m]
  const [helixBandM, setHelixBandM] = useState(1.0);       // 帯の幅[m]
  // ══ 「失敗例」の作図ボタン・2026-10-04 ══
  // 【なぜ隠すか】ユーザー指摘：
  //   「例を挙げるたびに個別で作っている。3D CAD は形の種類を持たず、
  //     断面(Profile)×経路(Curve)×操作(Feature) の抽象で全部作る」。
  //   下の4つは**その指摘どおり、形ごとに個別実装してしまったもの**。
  //   作り直すまで邪魔なのでツールバーから引っ込める。**消さない**（描いた形も記録も生きている）。
  //   出したいときは〔🧪 失敗例〕を押す。
  // 【1か所の表にする理由】ボタンごとに if を書くと、次に足したとき必ずどれか漏れる。
  //   出す・出さないの条件は「失敗例ON か」だけ（Codex監査）。
  const [bldLegacyOn, setBldLegacyOn] = useState(false);
  // 隠れているモードが選ばれたまま残らないよう、矩形へ戻す
  useEffect(() => {
    if (!bldLegacyOn && BLD_LEGACY_TOOLS.indexOf(bldDrawMode) >= 0) {
      setBldDrawMode('rect'); setPolyPoints([]); setPolyMousePos(null);
    }
  }, [bldLegacyOn, bldDrawMode]);
  // ══ 〔⌁ 掃引〕作図の属性・2026-10-04 ══
  // 【これが作図の入口の作り直し】ユーザー指摘「形ごとに個別の機能を作るな」への答え。
  //   形ごとのボタン（ケーブルラック・配管・梁…）を足さない。利用者が決めるのは
  //   **断面 × 経路 × 向き** の3つだけで、掛け算で形が出る。
  // 【既定は 'draw'＝輪郭を描く】3DCADの主手順は『平面に描く → 引き抜く』（2026-10-06 ユーザー裁定）。
  //   決まった形（矩形・円・H形鋼…）は**近道**であって主役ではない
  const [sweepProfile, setSweepProfile] = useState('draw');  // 断面の種類（BC_PROFILES の行）
  const [sweepWM, setSweepWM] = useState(0.6);      // 幅・直径[m]
  const [sweepHM, setSweepHM] = useState(0.1);      // 高さ・成[m]
  const [sweepTM, setSweepTM] = useState(0.012);    // 板厚[m]（H形鋼だけ）
  const [sweepBulgeM, setSweepBulgeM] = useState(0);// 曲がり量[m]（点が2つのときだけ・円弧になる）
  // 【通りは輪郭と別に持つ・2026-10-19】〔⌁ 沿わせる〕は **断面 × 通り** の操作。
  //   1つの polyPoints に輪郭と通りを兼ねさせていたので、面を作ってから通りを描けなかった
  //   （描いた輪郭を渡す先が無く、押せなくして理由を出していた）。
  //   回すが軸を revolveAxis に分けて持っているのと同じ形にする。
  const [sweepWay, setSweepWay] = useState([]);   // 通り（作業平面の中の点列。点ごとに z）
  const [sweepBaseM, setSweepBaseM] = useState(4);  // 下端の高さ[m]
  const [sweepUpright, setSweepUpright] = useState(true); // 断面を経路に立てるか
  // 【断面の置き方・2026-10-26 ユーザー要望】
  //   「その向きとか決められるようにしないとダメじゃないの？」
  //   「中心（重心）とオレンジ点線が同じになるようにするとかしないと描きにくい」
  const [sweepRollDeg, setSweepRollDeg] = useState(0);        // 道のまわりに何度回すか
  const [sweepAnchor, setSweepAnchor] = useState('bottom');   // 通りに乗せる点
  // 【向きを選べる操作は1つだけ・述語は1か所・2026-10-18 advisor 監査】
  //   〔断面を立てる／横たえる〕は全モードで出ていたが、値を読むのは〔⌁ 沿わせる〕だけで、
  //   ほかは押しても黙って何も起きなかった（ユーザー報告）。
  //   入口は消さない（対象が無いと機能ごと無いように見えるため・裁定済み）。
  //   押せなくして理由を出す＝回せない・沿わせられない と同じ扱いにする。
  //   【描いた輪郭では選べない・2026-10-19】横たえると断面の高さが経路方向のずれに化けて
  //     厚みが0に潰れる（advisor 監査）。決まった断面のときだけ選べる。
  const 断面の向きを選べるか = (k) => ((k || sweepMode) === 'path' && sweepProfile !== 'draw');
  // その操作で**実際に使われている**向き。ボタンの見た目も確定の計算もここから引く
  //   （値と表示を別々に書くと「立てると表示しながら横たえている」が起きる＝実測）
  const 実効の断面の向き = (k) => {
    const m = (k || sweepMode);
    // 描いた輪郭はいつも立てる（寝かせると厚み0に潰れる）
    if (m === 'path') return (sweepProfile === 'draw') ? 'upright'
                           : (sweepUpright ? 'upright' : 'flat');
    // 引き抜く：接線が真上なので断面を立てると yaw を読めず、ひねりが効かなくなる
    if (m === 'twist') return 'flat';
    // 回す・らせん：断面は『軸からの距離 × 高さ』。寝かせると高さが水平のずれに化けて潰れる
    return 'upright';
  };
  // 【作り方は3択・2026-10-06】形ごとのボタンを増やさず、1つの入口の中で選ぶ。
  //   'path'    通りをクリックして描く → ラック・配管・梁・屋根
  //   'revolve' 軸を1点クリック（360°回す） → ドーム・タンク・球
  //   'helix'   軸を1点クリック（回りながら上がる） → バネ・ドリル・らせんの手すり
  //   'twist'   軸を1点クリック（真上へ引き抜く。ひねり・先細りを掛けられる）
  //   【既定は 'twist'】『平面作図 → 引き抜き』が3DCADの主手順（2026-10-06 ユーザー裁定）
  // 【操作は未選択で始める・2026-10-14 ユーザー裁定／Codex監査 01a135be】
  //   null ＝「面はあるが、何をするかまだ決めていない」。旗を別に足さない（同じ意味の
  //   状態を2つ持たない・Codex）。null の間は確定しても立体にしない。
  //   動詞を押す／面を掴んで引く と決まり、そこで初めて形になる。
  const [sweepMode, setSweepMode] = useState(null);  // null | 'twist' | 'revolve' | 'path' | 'helix'
  // 〔⬆ 引き抜く〕のひねり（度）。0 ならただの押し出し、1080 ならドリルの刃になる。
  //   らせんの『回る角度』とは意味が違うので値を分ける（片方を変えたら他方が動く、を避ける）
  const [sweepTwistDeg, setSweepTwistDeg] = useState(0);
  // 〔⟳ 回す〕の角度。360 で一周、180 なら半分だけ（切った見せ方・樋）
  const [sweepRevDeg, setSweepRevDeg] = useState(360);
  // 【回すの軸はユーザーが決める・2026-10-14 ユーザー裁定／Codex監査 01a135be】
   //  「回すボタンを押した段階で軸を設定するようにしてその軸を決定した後ドラッグで
   //    回転角度を決められるようにすればいいだろ」
   //  作業平面の上の座標（正面なら横位置・横なら奥行位置）。null＝まだ決めていない。
   //  【軸待ちは一時状態に閉じ込める】未設定のときだけクリックを軸置きに使い、
   //    決まったら〔⟳ 軸を置き直す〕で戻す（曖昧なクリックを残さない・Codex）
  const [revolveAxis, setRevolveAxis] = useState(null);
  // 回る向き。+1＝軸の向き(A→B)の右ねじ／-1＝その逆（2026-10-18 ユーザー要望）
  const [revolveDir, setRevolveDir] = useState(1);
  // 【いまの面では回せないか・2026-10-14 ユーザー報告／Codex監査 01a135be】
  //   「面作った後回すが選べんけど。」押せないボタンとツールチップだけでは理由に
  //   たどり着けない。帯（案内）とボタンが**同じ述語**を見て、理由と一手を同じ視線上に出す。
  //   【2026-10-15 で解消】上から描いた輪郭も「面の中の軸」で回せるようになった
  //   （軸が水平になる＝倒す）。どの面でも回せるので、禁止は無い。
  //   残しているのは、将来また「この面では回せない」が出たときに1か所で決めるため。
  const 回せない面か = () => false;
  // 輪郭が軸をまたいでいるか（またぐと回転体にならない）。案内と作成の判定が同じ式を使う
  // 【軸は2点で決める・2026-10-16 ユーザー要望】「3次元的に見てどこからどこというのを
  //   決める必要がある」。1回目＝始点、2回目＝終点、3回目＝また始点から置き直し。
  //   【長さ0の軸を作らない・2026-11-21 advisor監査】ダブルクリックはクリック2回が先に出るので、
  //     2点目が1点目と同じ場所になり得る（通りには同じ点の重複除けがあるが軸には無かった）
  const 回す軸を置く = (p) => setRevolveAxis(prev => {
    if (prev && prev.a && !prev.b) {
      if (Math.hypot(p.x - prev.a.x, p.y - prev.a.y) < MINOR * 0.4) return prev;
      return { a: prev.a, b: { x: p.x, y: p.y } };
    }
    return { a: { x: p.x, y: p.y }, b: null };
  });
  const 軸をまたぐか = () => {
    // 【展開した形で見る・段1-b】頂点はまたがず円弧だけが軸をまたぐ形がある
    const 枠2 = 回す軸の枠(); if (!枠2 || !輪郭は面か) return false;
    const d = 輪郭の点列.map(p => 軸からの距離(p, 枠2));
    return d.some(v => v > 0.05) && d.some(v => v < -0.05); };
  // 【スケッチが確定したか・2026-10-06】Fusion 360 と同じく、描き終えても**まだ立体にしない**。
  //   操作（引き抜く/回す/らせん）を選んだ**その場で**立体になる
  //   （〔✓ 作る〕は 2026-10-12 に廃止。「平面が確定した段階で完了」）。
  //   スケッチは残るので、操作を切り替えて何度でも試せる（Fusion はスケッチが履歴に残り、
  //   同じスケッチから複数のフィーチャーを作れる）。
  const [sketchDone, setSketchDone] = useState(false);
  // 【作業平面・2026-10-06 ユーザー裁定】スケッチは**選んだ平面の上の2D座標**。
  //   操作がその平面をどう使うかを決める（Codex）：
  //     引き抜く … その平面の法線方向へ伸ばす
  //     回す     … その平面**内**の軸まわりに回す（＝鉛直断面を回すので立面で描くのが正しい）
  //   'plan'=上から(X-Y) / 'elev'=正面から(X-Z) / 'side'=横から(Y-Z)。bldDrawView と同じ値。
  //   【なぜ要るか】平面図(X-Y)に描いた輪郭を回すと、その輪郭は鉛直面に立てられるので
  //     **平面図の縦が高さになる**。「xy平面で描いたのに yz 平面として解釈される」と言われた。

  // 建屋の作図から出たらスケッチを畳む。別の所をクリックしただけでは消さない（Codex）。
  //   【置き場所】bldEditMode / bldDrawMode を読むので、**それらの宣言より後ろ**に置く。
  //   前に置くと依存配列がレンダー時に評価されて『初期化前に参照』で画面が真っ白になる
  useEffect(() => { if (!bldEditMode || bldDrawMode !== 'sweep') setSketchDone(false); },
    [bldEditMode, bldDrawMode]);
  const sweepRevolve = (sweepMode === 'revolve');   // 既存の呼び出しのため残す
  // 通りを描くとき「次に打つ点の高さ」。点ごとに記録されるので、上下にうねる通りが引ける
  const [sweepNextZ, setSweepNextZ] = useState(0);
  // らせんの欄（回りながら上がる）
  const [sweepTurnDeg, setSweepTurnDeg] = useState(720);  // 回る角度（720＝2回転）
  const [sweepRiseM, setSweepRiseM] = useState(3);        // 上がる高さ[m]
  const [sweepR1, setSweepR1] = useState(1);              // 先の太さ（1＝一定・0.1＝細くなる）
  // 描いた形を何にするか。'bld'＝建屋（階・仕切り・扉）／'body'＝立体（押し引き・結合・くり抜き）
  const [bldDrawTarget, setBldDrawTarget] = useState('bld');
  // ══ CSGボディ（プリミティブ＋ブーリアン）・2026-09-26 ══
  // 【ユーザー指摘】形の型を1つずつ足す方式では「世の中の建物」は網羅できない。
  //   bodies は「作り方の履歴」（円柱を置く→球を足す→箱で切る…）で形を持つ。
  //   既存の blocks[] は残し、複雑な形だけこちらへ逃がす（Codex監査）。
  const [csgSolids, setCsgSolids] = useState([]); // 評価した結果（faces）。描画だけに使う
  const bodyCounter = useRef(0);
  // 保存のときに「今の bodies」を読むための口（buildingsRef と同じ作法）
  const bodiesRef = useRef([]);
  bodiesRef.current = bodies;
  const groundAreasRef = useRef([]);
  groundAreasRef.current = groundAreas;
  // 評価した結果（外接箱）を読む口。新しい段を「今の立体の真ん中」に置くのに使う
  const csgSolidsRef = useRef([]);
  csgSolidsRef.current = csgSolids;
  const [polyPoints, setPolyPoints] = useState([]); // points being drawn in polygon mode
  const [polyMousePos, setPolyMousePos] = useState(null); // current mouse pos during polygon drawing
  // ════ 描いた輪郭の形・段1-b・2026-11-21 advisor監査 ════
  //   polyPoints は**原本**（頂点＋任意の膨らみ b＝その頂点から次の頂点までの円弧。solidModel の sketchExpand の約束）。
  //   **形として読む所**（下見の面・回す・引き抜く・重心・軸をまたぐか・面になるか）は全部この展開を読む。
  //   **頂点として読む所**（番号の丸・寸法の起点・始点の判定）は polyPoints のまま。
  //   回す側らは点を鏡映し、軸をまたぐと切るので、膨らみを持ったまま渡すと符号が反り区間が割れる＝先に展開する。
  const 輪郭の展開 = useMemo(() => ((typeof sketchExpandWithIndex === 'function')
    ? sketchExpandWithIndex(polyPoints, { closed: true })
    : { 点ら: polyPoints.map(p => ({ x: p.x, y: p.y })), 頂点の位置: polyPoints.map((_, i) => i) }),
    [polyPoints]);
  const 輪郭の点列 = 輪郭の展開.点ら;
  // 【面になり得るか・述語1つ】頂点の数では決めない（直線＋円弧の D 形は頂点2つで面になる）。
  //   展開した形が3点以上で、面積が0でないこと。頂点数の直書きを残すと窓ごとに「閉じられる／閉じられない」が割れる
  const 面になり得るか = (pts) => {
    const e = (typeof sketchExpand === 'function') ? sketchExpand(pts || [], { closed: true }) : (pts || []);
    if (e.length < 3) return false;
    let s = 0; for (let i = 0; i < e.length; i++) { const a = e[i], c = e[(i + 1) % e.length];
      s += a.x * c.y - c.x * a.y; }
    return Math.abs(s) > 1e-6;
  };
  const 輪郭は面か = useMemo(() => 面になり得るか(polyPoints), [polyPoints]);
  // 輪郭の区間の道具（'line'｜'arc3'｜'tangent'・表は 区間の道具）と、3点円弧の控え
  //   控え＝1回目のクリックで決めた終点 {終点, 閉じる, 頂点数}。頂点数が今の頂点数と合わなければ無効
  //   （輪郭を捨てる所が20か所以上あるので、場面を列挙して捨てる代わりに数で見る・advisor 条件）
  const [sketchSegTool, setSketchSegTool] = useState('line');
  const [arc3Pending, setArc3Pending] = useState(null);
  // 作図の数値の小窓（引っ張った後の高さ・角度、作図中の辺の長さ）。{x, y, kind, 中, …}
  //   説明は 引き抜く高さに丸める の上。kind:'length' は段1-a（作図中の寸法の数値入力）
  const [sketchNum, setSketchNum] = useState(null);
  // 最後のマウスの画面座標（数字キーで小窓を開く位置。作業平面の座標から逆算しない）
  const _最後のマウスRef = useRef({ x: 0, y: 0 });

  // 【作業平面は記録1つ・段0-b・2026-11-20 advisor監査】
  //   旧: bldDrawView（'plan'|'elev'|'side' の文字列）を状態に持ち、面の位置は名前ごとに固定。
  //   新: 作業平面の記録を唯一の状態にし、bldDrawView は**派生**
  //     （face＝作った箱の面〔段0-c〕では null）。状態を2つ持たない。
  //   setBldDrawView(k) は軸を選ぶ口として残す（呼び口は従来のまま）。
  //   【段0-c】記録の種類は3つ：
  //     {kind:'base', axis}                     … 上から・正面・横
  //     {kind:'pick', 戻り先}                   … 面を選んでいる最中（平面ではない＝描けない）。Esc で戻り先へ
  //     {kind:'face', 由来:{solidId,faceId,…}, 枠} … 作った箱の面。面の名前と選んだ時点の枠
  //   kind の分岐は 作業平面の枠・この窓は受けられるか・面の役 の中だけに閉じる（SPEC §1）。
  const [作業平面, set作業平面] = useState({ kind: 'base', axis: 'plan' });
  const bldDrawView = (作業平面 && 作業平面.kind === 'base') ? 作業平面.axis : null;
  const setBldDrawView = (k) => set作業平面(p =>
    (p && p.kind === 'base' && p.axis === k) ? p : { kind: 'base', axis: k });
  //   【窓が受けられるか・述語は1つ】旧は各窓が `bldDrawView === '自分の名前'` を手書き（約20か所）。
  //   記録が face になると文字列比較が全部偽になり、理由も出ずに描けなくなるので、ここに寄せる。
  //   窓：'plan'（平面図）/'elev'（断面図）/'side'（側面図）/'cab'（3次元図）。理由も返す。
  const この窓は受けられるか = (窓) => {
    const r = 作業平面;
    if (!r) return { 可: false, 理由: '作業平面が決まっていません' };
    if (r.kind === 'base') {
      if (窓 === 'cab' || 窓 === r.axis) return { 可: true, 理由: '' };
      return { 可: false, 理由: '作業平面は ' + (作業平面の名[r.axis] || r.axis) + ' です' };
    }
    if (r.kind === 'pick') return { 可: false, 理由: '3次元図で、描きたい箱の平らな面をクリックしてください（Esc で戻る）' };
    if (窓 === 'cab') return { 可: true, 理由: '' };
    return { 可: false, 理由: '選んだ面には3次元図でだけ描けます' };
  };
  //   【操作が作業平面を読むか・段0-c】引き抜く・回すは枠（面の位置と向き）を読む。
  //   沿わせる・らせんは通りや軸を平面図の座標として使う（枠を読まない）ので、選んだ面の上では作れない。
  //   ボタンを押せなくして理由を出す（述語はここ1つ）。基本3面は従来どおり。
  const この操作を選べるか = (op) => {
    if (!作業平面 || 作業平面.kind !== 'face') return { 可: true, 理由: '' };
    if (op === 'twist' || op === 'revolve') return { 可: true, 理由: '' };
    return { 可: false, 理由: '選んだ面の上ではまだ使えません（引き抜く・回すが使えます）' };
  };
  //   描き始めたら作業平面（軸も位置も）を変えない。ボタンと位置の欄が同じこれを読む
  const 作業平面を変えられない = () => (polyPoints.length > 0 || sketchDone);
  // 【描いた輪郭を3次元図に出す・2026-10-06 ユーザー裁定】
  //   「平面図で作ったならある程度の厚みを持って生成し3次元図に見えるようにする→その後引っ張る」
  //   【なぜ薄い板か】面1枚だと真横から見たとき消えて、また『見えない』になる（Codex）。
  //     作業平面の**法線方向**に薄くする： plan は Z に薄く／elev は Y に薄く／side は X に薄く。
  //   【なぜ solids に混ぜないか】建屋の同期・保存を汚さない。描画用の配列にだけ足す
  //     （CSG の立体と同じ扱い）。これは『できる形の下見』ではなく**スケッチ面の3D表示**。
  const sketchSolids = useMemo(() => {
    if (!bldEditMode || bldDrawMode !== 'sweep') return [];
    if (!輪郭は面か) return [];   // 段1-b：展開した形で面かを見る
    const mpp = (typeof METERS_PER_PX === 'number' && METERS_PER_PX > 0) ? METERS_PER_PX : 0.1;
    // 【面1枚にする・2026-10-06 ユーザー報告】
    //   薄い板（上面・下面・側面）にしたら、半透明の面が重なって**回すたびに残像**に見えた。
    //   Fusion のスケッチも面1枚。真横から細くなるのは普通で、層が分かれるより誤解が少ない。
    let 面A;
    if (_枠から読むか()) {
      const 枠 = 作業平面の枠(作業平面, sweepBaseM); if (!枠) return [];
      面A = 輪郭の点列.map(p => 面の点を立体へ(p, 枠));
    } else if (bldDrawView === 'elev') {
      const yc = TH / 2;                   // 断面図(X-Z)：x=横, y=高さ
      面A = 輪郭の点列.map(p => ({ x: p.x, y: yc, z: p.y * mpp }));
    } else if (bldDrawView === 'side') {
      const xc = TW / 2;                   // 側面図(Y-Z)：x=奥行, y=高さ
      面A = 輪郭の点列.map(p => ({ x: xc, y: p.x, z: p.y * mpp }));
    } else {
      const z = sweepBaseM || 0;           // 平面図(X-Y)：下端の高さに置く
      面A = 輪郭の点列.map(p => ({ x: p.x, y: p.y, z: z }));
    }
    const faces = [{ vertices: 面A, type: 'sketch' }];
    return [{ id: '__sketch', buildingId: '__sketch', label: 'スケッチ',
              color: '#2563EB', _sketch: true, faces }];
  }, [bldEditMode, bldDrawMode, bldDrawView, 作業平面, polyPoints, sweepBaseM]);

  // 【3次元図で輪郭を描いている最中か・1か所で決める・2026-10-11】
  //   読む所が3つある（カメラの入口＝ref／図の上の面が入力を取るか＝描画）。
  //   条件を場所ごとに手書きすると、必ずどこかが漏れる（CLAUDE.md）。
  const _3d作図中 = !!(bldEditMode && bldDrawMode === 'sweep' && sweepProfile === 'draw');
  //   【陽性対照】window.__SKETCH_FACE_PASSTHRU = false で従来＝面が入力を奪う
  //     （＝輪郭の内側でダブルクリックしても確定できない状態に戻る）。
