    while (queue.length > 0) {
      const nid = queue.shift();
      if (visited.has(nid)) continue;
      visited.add(nid);
      segs.forEach(s => {
        if (s.from === nid || s.to === nid) {
          segIds.add(s.id);
          if (!visited.has(s.from)) queue.push(s.from);
          if (!visited.has(s.to)) queue.push(s.to);
        }
      });
    }
    return { nodeIds: visited, segIds };
