            const lookAtE = cabScreenToGroundPoint(CAB_W / 2, CAB_H / 2, camAz, camEl, camZoom, camPanX, camPanY);
            const camEX = Math.max(30, Math.min(ELEV_W - 30, lookAtE.x + 50 / _ez));
