                  const _lm = pdcLabelMetrics(_pxSpan, cabSvgScale, _pinned, { pxPerMeter: _cabPxPerMeter() });
                  const _csc2 = _lm.csc;
                  const _showLabel = _lm.show;
                  const _nFS = _lm.fs;
                  const _nSW = _lm.strokeW;
                  // ユーザー設定オフセット（viewBox単位・盤回転には追従させない = 常に画面平行移動）
                  const _lo = pp.labelOffset || { dx: 0, dy: 0 };
                  // ずらし量は「盤の見かけの大きさの何倍か」。盤と同じ割合で動くので、
