                  // ずらし量の単位は _pxSpan なので、遠景では基準の3(viewBox)が0.1px相当まで潰れ、
                  // 文字だけ11pxに引き上げるとラベルが盤や📷に密着する。
                  const _gap = _lm.gap;
                  const _lx = _bx0 + _gap + (_lo.dx || 0) * _pxSpan;
                  const _ly = _by0 - _gap + (_lo.dy || 0) * _pxSpan;
                  const _lmDragging = !!(labelMoveDrag && labelMoveDrag.id === pp.id);
