        const _liveLabel = _liveZPx >= 0 ? `${Math.floor(_liveZPx / MAJOR) + 1}F` : `B${Math.ceil(-_liveZPx / MAJOR)}`;
        const _iW = 42, _iH = 46, _iSym = 28, _iF = 11;

